# ===== BEGIN portable_ai/model.rb =====
# PortableAI normalized model.
#
# The core deliberately accepts and returns plain Hash/Array values. Engine adapters own
# every object lookup and legality check; callers only need to know this small interface:
#
#   PortableAI.plan(snapshot, config, rng) -> {
#     "actions" => [decision, ...], "diagnostics" => {...}
#   }
#
# Required snapshot keys:
#   "actors"  Array of AI battlers. Each actor has "index" and legal "actions".
#   "targets" Array of opposing active battlers.
#
# An action is already legal and has "type" ("move" or "switch"), "base_score", and the
# registration fields the adapter needs ("slot", plus "target" for targeted moves).
# Everything else is optional evidence used to improve the score.

module PortableAI
  VERSION = "0.6.2" unless const_defined?(:VERSION)

  module Model
    DEFAULT_CONFIG = {
      "deterministic" => true,
      "noise"         => 0,
      "switching"     => true,
      "memory"        => true,
      "coordination"  => true,
      "knowledge"     => "fair",
      # A voluntary switch must name an escape reason rather than merely outscoring
      # the available moves (Core.score_switch). Set false to restore the pre-0.3.0
      # score-competition behaviour for A/B runs.
      "switch_gate"   => true,
      # How loudly a switch candidate's incoming type risk counts against its
      # offensive matchup, in Core.score_switch. 1.0 makes the two exactly as loud as
      # each other; it was chosen for that symmetry, not swept, so this is a knob and
      # not a constant. 0.0 disables the defensive term and reproduces 0.3.1 exactly.
      "switch_risk_weight" => 1.0,

      # 0.4.0 move-policy rules. Each reproduces 0.3.2 exactly when off, so the
      # gauntlet can A/B any one of them without rebuilding (Data/ai_harness.txt ->
      # $PORTABLE_AI_CONFIG -> Adapter.config_for).
      #
      # Ask whether healing changes who is alive at the end of the turn, instead of
      # scoring recovery on the healer's own HP alone (Core.score_move). False
      # restores the flat heal_under_lethal_threat -80.
      "heal_gate"       => true,
      # How loudly a move's hit chance discounts its damage and its lethal bonus:
      # Reborn's (accuracy + 100) / 200 (PokeBattle_AI_2.rb:3349). 0.0 ignores
      # accuracy, which is 0.3.2; 1.0 is Reborn's own weight.
      "accuracy_weight" => 1.0,
      # Read the exported move priority against the actor's speed order, so a KO that
      # cannot land before the actor dies stops being scored as a KO.
      "priority_gate"   => true,
      # Charge stat-dropping and self-KO moves for what they cost.
      "self_cost"       => true,
      # The -400 "you die whatever you click" rules (heal_cannot_resolve,
      # ko_never_lands) only count a threat as certain when the adapter says the
      # foe's move cannot fail to happen: 100% accurate and the foe awake
      # (actor["certain_incoming_damage_pct"]). Measured on set_c, the loose
      # predicate was right 85% of the time under those conditions and 28% outside
      # them (PORTABLE-AI-REBORN.md, "Decision-log run"). False is 0.4.0.
      "strict_threat"   => true,

      # 0.5.0 tables. Reborn is mostly per-move and per-ability branches (494 move
      # function branches, 1,161 ability mentions that are decision logic), and single
      # per-turn rules stopped moving wins after 0.3.0. These four ship that breadth as
      # data read by a few generic rules, measured as one batch. All four false
      # reproduces 0.4.1 battle-for-battle.
      #
      # Move side effects: secondary status, flinch, stat drops, recoil, drain,
      # multi-hit, item removal, speed control, first-turn and delayed moves.
      "side_effects"    => true,
      # Abilities that change what a move is worth without changing its damage:
      # Sturdy/Focus Sash defeating a kill call, Unaware, Contrary, Justified,
      # Regenerator, and the status-deterrent table.
      "ability_rules"   => true,
      # Entry cost as its own term: hazards and the real incoming estimate on the
      # switch candidate, in place of the type-only proxy.
      "entry_rules"     => true,
      # 0.6.0. Hits-to-KO both ways, computed once in Core.damage_race and read by the
      # setup gate and the switch-in ladder. False reproduces 0.5.0 exactly.
      "damage_race"     => true,
      # The switch ESCAPE reason built on the same helper, kept separate and OFF.
      # Phase A measured stock Reborn refusing to leave a race it loses by a whole turn
      # even with an immune bench available (shouldSwitch? = -50), so this is a
      # Radical-Red-cited experiment the A/B can turn on, not a reproduction. The
      # switch programme was closed on evidence (PORTABLE-AI-DIAGNOSIS.md §4) and this
      # must not reopen it by default.
      "damage_race_switch" => false,
      # Doubles-only rules: partner absorbs, redirection, partner healing, and the
      # flatter value of priority when a second foe acts regardless.
      "format_rules"    => true,

      # 0.6.2 bugfix batch. Every one of these was READ OFF a turn-by-turn readout of
      # the 0.6.1 set_c run, not proposed from the source
      # (PORTABLE-AI-REBORN.md, "Turn-by-turn readout pass on set_c"), and each is its
      # own key so the batch can be ablated one row at a time. ALL SEVEN FALSE
      # REPRODUCES 0.6.1 BATTLE-FOR-BATTLE -- that control run is what makes any
      # number from this version mean anything.
      #
      # A spread move carries no registration target, so target_for returned nil and
      # every Earthquake was scored against a phantom 100% target: never lethal, and
      # ko_never_lands could not fire for it either. Read the adapter's exported
      # target_hp_pct instead.
      "spread_target_hp" => true,
      # A knockout is a knockout: once lethal, the type-effectiveness term and the
      # secondaries that only matter to a survivor stop counting, so accuracy decides
      # between two kills. Fire Blast (85%) was beating Dragon Claw (100%) for the
      # same KO purely on the super-effective bonus.
      "lethal_flat"      => true,
      # Charge a switch candidate that is dead before it moves. score_switch already
      # computed the subtraction for preserve_low_hp_actor and never rejected on it.
      "entry_death"      => true,
      # Wish re-clicked with a Wish already pending. The adapter now reports
      # PBEffects::Wish through effect_active, the same channel the screens use.
      "wish_pending"     => true,
      # first_setup was decided by a memory counter that apply_memory zeroes on any
      # non-setup action, so a +2 sweeper that attacked once was "first setting up"
      # again. Drive it off the stages the actor is actually carrying.
      "setup_stage"      => true,
      # Do not re-click a move that failed last turn against the same target. Reborn
      # keeps the flag itself for Stomping Tantrum (PBEffects::Tantrum); this reads it.
      "move_memory"      => true,
      # Yawn into an already-drowsy target. Same bug class as 0.6.1's Leech Seed: the
      # move writes an EFFECT, not a status condition, so pbCanSleep? answers "yes"
      # about a target the engine will refuse (PokeBattle_MoveEffects.rb:249).
      "yawn_gate"        => true
    }

    def self.config(overrides)
      out = {}
      DEFAULT_CONFIG.each { |k, v| out[k] = v }
      (overrides || {}).each { |k, v| out[k.to_s] = v }
      out
    end

    def self.validate(snapshot)
      raise ArgumentError, "snapshot must be a Hash" if !snapshot.is_a?(Hash)
      actors = snapshot["actors"]
      targets = snapshot["targets"]
      raise ArgumentError, "snapshot actors must be a non-empty Array" if !actors.is_a?(Array) || actors.empty?
      raise ArgumentError, "snapshot targets must be an Array" if !targets.is_a?(Array)
      actors.each do |actor|
        raise ArgumentError, "actor must be a Hash" if !actor.is_a?(Hash)
        raise ArgumentError, "actor index missing" if actor["index"].nil?
        actions = actor["actions"]
        raise ArgumentError, "actor actions must be an Array" if !actions.is_a?(Array)
        actions.each do |action|
          validate_action(action)
        end
      end
      true
    end

    def self.validate_action(action)
      raise ArgumentError, "action must be a Hash" if !action.is_a?(Hash)
      kind = action["type"]
      raise ArgumentError, "unknown action type #{kind.inspect}" if kind != "move" && kind != "switch"
      raise ArgumentError, "action slot missing" if action["slot"].nil?
      if kind == "move"
        raise ArgumentError, "move id missing" if action["move_id"].nil?
      end
      true
    end

    def self.number(value, fallback)
      return fallback if value.nil?
      value.to_f
    rescue
      fallback
    end

    def self.truthy(value)
      value == true || value == 1 || value == "1" || value == "true"
    end

    def self.copy_hash(source)
      out = {}
      (source || {}).each { |k, v| out[k] = v }
      out
    end
  end
end
# ===== END portable_ai/model.rb =====

# ===== BEGIN portable_ai/effects.rb =====
# Canonical move knowledge keyed by internal move ID, never by Essentials function code.
# Adapters convert PBMoves::FOO / GameData IDs to the uppercase String "FOO".

module PortableAI
  module Effects
    TABLE = {}

    # Tags accumulate: a move may be listed by more than one call (Explosion is both
    # a spread move and a self-KO), so the table is order-independent.
    def self.add(ids, tags)
      ids.each do |id|
        known = TABLE[id] || []
        merged = known.clone
        tags.each { |tag| merged << tag if !merged.include?(tag) }
        TABLE[id] = merged
      end
    end

    # "heal" alone is the flat half-HP recovery the core assumes. The two refinements
    # exist because the 0.4.0 heal gate asks whether healing outruns the incoming hit,
    # which needs the amount: Rest refills completely, and the weather heals pay only
    # a quarter in sand or hail.
    add(%w[RECOVER ROOST SOFTBOILED MILKDRINK SLACKOFF
           HEALORDER SHOREUP], ["heal"])
    add(%w[MOONLIGHT SYNTHESIS MORNINGSUN], ["heal", "heal_weather"])
    add(%w[REST], ["heal", "heal_full", "self_sleep"])
    add(%w[WISH], ["delayed_heal"])
    add(%w[PAINSPLIT], ["variable_heal"])

    # Defensive setup was missing entirely: the list was offensive boosts only, so
    # Iron Defense and Amnesia were scored as plain unknown status moves. Curse is
    # here for the non-Ghost form; the adapter's own type check keeps the Ghost form
    # (which costs half the user's HP) out.
    add(%w[SWORDSDANCE NASTYPLOT DRAGONDANCE QUIVERDANCE CALMMIND
           BULKUP COIL SHELLSMASH GEOMANCY TAILGLOW
           AGILITY ROCKPOLISH AUTOTOMIZE WORKUP GROWTH
           IRONDEFENSE AMNESIA COSMICPOWER ACIDARMOR BARRIER STOCKPILE
           HONECLAWS CURSE DEFENDORDER], ["setup"])
    add(%w[BELLYDRUM], ["setup", "hp_cost_half"])
    add(%w[SOLARBEAM SOLARBLADE], ["charge_solar"])
    add(%w[PROTECT DETECT KINGSSHIELD SPIKYSHIELD BANEFULBUNKER
           OBSTRUCT SILKTRAP BURNINGBULWARK], ["protect"])
    add(%w[SUBSTITUTE], ["substitute"])

    # Status kinds let adapters derive immunity facts (burn vs Fire-types, poison vs
    # Steel, powder vs Grass, paralysis vs Electric). "typed_status" marks moves whose
    # own type immunity blocks them (Thunder Wave vs Ground) — Glare deliberately lacks
    # it because modern engines let it hit Ghost-types.
    add(%w[THUNDERWAVE], ["status", "paralyze", "typed_status"])
    add(%w[GLARE], ["status", "paralyze"])
    add(%w[STUNSPORE], ["status", "paralyze", "powder"])
    add(%w[WILLOWISP], ["status", "burn"])
    add(%w[TOXIC], ["status", "poison"])
    add(%w[POISONPOWDER], ["status", "poison", "powder"])
    add(%w[SPORE SLEEPPOWDER], ["status", "sleep", "powder"])
    add(%w[HYPNOSIS DARKVOID], ["status", "sleep"])
    # Yawn puts the target to sleep NEXT turn by writing PBEffects::Yawn, so it fails
    # against an already-drowsy target while pbCanSleep? still says yes. It carries its
    # own tag purely so the adapter's status_blocked? can find it without a move-name
    # lookup -- the same shape as "drain" on LEECHSEED below.
    add(%w[YAWN], ["status", "sleep", "drowsy"])
    add(%w[CONFUSERAY SWAGGER FLATTER], ["status", "confuse"])
    add(%w[LEECHSEED], ["status", "drain"])
    add(%w[TAUNT ENCORE TORMENT DISABLE HEALBLOCK PSYCHICNOISE], ["disrupt"])
    add(%w[HAZE CLEARSMOG], ["reset_stages"])

    add(%w[STEALTHROCK SPIKES TOXICSPIKES STICKYWEB], ["hazard"])
    add(%w[RAPIDSPIN DEFOG MORTALSPIN TIDYUP], ["hazard_remove"])
    add(%w[REFLECT LIGHTSCREEN AURORAVEIL SAFEGUARD MIST], ["screen"])

    add(%w[UTURN VOLTSWITCH FLIPTURN PARTINGSHOT TELEPORT], ["pivot"])
    add(%w[ROAR WHIRLWIND DRAGONTAIL CIRCLETHROW], ["force_switch"])
    add(%w[BATONPASS], ["baton_pass"])
    add(%w[TRICK SWITCHEROO KNOCKOFF CORROSIVEGAS], ["item_control"])
    # Knock Off alone actually REMOVES the item; Trick and Switcheroo swap it, which
    # is a different trade the core does not price. Reborn's knockcode (:8072) is a
    # short whitelist and nothing else, so the tag exists to reach that one rule.
    add(%w[KNOCKOFF], ["item_removal"])

    add(%w[FOLLOWME RAGEPOWDER SPOTLIGHT], ["redirect"])
    # 0.5.0 tables. "speed_control" is anything that changes who moves first;
    # "field_speed" narrows that to the two whole-turn investments, which are the only
    # ones with a "already active, do not repeat" case. "first_turn_only" and
    # "delayed_damage" each need one engine fact (turncount, effect_active) that the
    # adapter now exports. "partner_heal" is a move that does nothing at all in
    # singles.
    add(%w[TRICKROOM TAILWIND STICKYWEB ICYWIND ELECTROWEB ROCKTOMB
           BULLDOZE ICESPINNER], ["speed_control"])
    add(%w[TRICKROOM TAILWIND], ["speed_control", "field_speed"])
    add(%w[FAKEOUT FIRSTIMPRESSION], ["first_turn_only"])
    add(%w[FUTURESIGHT DOOMDESIRE], ["delayed_damage"])
    add(%w[HEALPULSE POLLENPUFF LIFEDEW FLORALHEALING], ["partner_heal"])
    add(%w[HELPINGHAND COACHING DECORATE], ["partner_support"])
    add(%w[WIDEGUARD QUICKGUARD MATBLOCK CRAFTYSHIELD], ["team_protect"])

    add(%w[EARTHQUAKE SURF DISCHARGE SLUDGEWAVE BOOMBURST EXPLOSION
           SELFDESTRUCT LAVAPLUME PETALBLIZZARD BULLDOZE], ["spread", "friendly_fire"])
    add(%w[ROCKSLIDE HEATWAVE DAZZLINGGLEAM MUDDYWATER BLIZZARD
           ICYWIND RAZORLEAF AIRSLASH SNARL TWISTER], ["spread"])
    add(%w[FAKEOUT EXTREMESPEED AQUAJET BULLETPUNCH MACHPUNCH
           ICESHARD SHADOWSNEAK SUCKERPUNCH VACUUMWAVE], ["priority"])

    # Moves that pay for their damage. "self_drop" wrecks the user's own offence for
    # the rest of the turn cycle; "self_ko" ends the user outright. Reborn charges
    # both (selfstatdrop :6118, deathcode :7779) and Portable over-used every move on
    # these two lists relative to it.
    add(%w[DRACOMETEOR OVERHEAT LEAFSTORM PSYCHOBOOST FLEURCANNON
           SUPERPOWER CLOSECOMBAT VCREATE HAMMERARM DRAGONASCENT], ["self_drop"])
    add(%w[EXPLOSION SELFDESTRUCT FINALGAMBIT MEMENTO HEALINGWISH
           LUNARDANCE], ["self_ko"])

    # Adapters that cannot compute Essentials function codes fall back to bare kind
    # tags ("secondary:burn"), so the core can still find the kind without a chance.
    # The Reborn adapter exports effect_kind/effect_chance from the code map instead
    # and never needs these; they exist so the same core runs on a thinner adapter.
    def self.kind_of(tags, prefix)
      head = prefix.to_s + ":"
      (tags || []).each do |tag|
        value = tag.to_s
        return value[head.length, value.length] if value.index(head) == 0
      end
      nil
    end

    def self.describe(move_id, supplied_tags)
      tags = []
      (TABLE[move_id.to_s.upcase] || []).each { |tag| tags << tag }
      (supplied_tags || []).each do |tag|
        value = tag.to_s
        tags << value if !tags.include?(value)
      end
      tags
    end

    def self.tagged?(move_id, supplied_tags, tag)
      describe(move_id, supplied_tags).include?(tag)
    end
  end
end
# ===== END portable_ai/effects.rb =====

# ===== BEGIN portable_ai/core.rb =====
# Engine-independent battle decision module.
# Requires model.rb and effects.rb to have been loaded first.

module PortableAI
  HARD_REJECT = -1000000

  def self.plan(snapshot, config, rng)
    Model.validate(snapshot)
    cfg = Model.config(config)
    random = rng || Kernel
    scored_by_actor = []

    snapshot["actors"].each do |actor|
      scored = []
      actor["actions"].each do |action|
        candidate = score_action(snapshot, actor, action, cfg, random)
        scored << candidate
      end
      raise ArgumentError, "actor #{actor['index']} has no usable actions" if scored.empty?
      scored.sort! { |a, b| compare_candidates(a, b) }
      scored_by_actor << scored
    end

    selected, joint = choose_joint(snapshot, scored_by_actor, cfg)
    updates = memory_updates(selected)
    {
      "actions" => selected,
      "memory_updates" => updates,
      "diagnostics" => {
        "version" => VERSION,
        "format" => snapshot["format"] || (snapshot["actors"].length > 1 ? "double" : "single"),
        "joint_adjustment" => joint,
        "candidate_counts" => scored_by_actor.map { |items| items.length },
        "rankings" => scored_by_actor
      }
    }
  end

  def self.score_action(snapshot, actor, action, config, rng)
    out = Model.copy_hash(action)
    out["actor_index"] = actor["index"] if out["actor_index"].nil?
    reasons = []
    score = Model.number(action["base_score"], 0.0)
    reasons << ["engine_base", score]

    if action["type"] == "switch"
      score = score_switch(snapshot, actor, action, config, score, reasons)
    else
      score = score_move(snapshot, actor, action, config, score, reasons)
    end

    adjustment = Model.number(action["score_adjustment"], 0.0)
    if adjustment != 0
      score += adjustment
      reasons << ["adapter_adjustment", adjustment]
    end

    noise = Model.number(config["noise"], 0.0)
    if !config["deterministic"] && noise > 0
      roll = rng.rand((noise * 2).to_i + 1) - noise
      score += roll
      reasons << ["difficulty_noise", roll]
    end

    out["score"] = score
    out["reasons"] = reasons
    out
  end

  def self.score_move(snapshot, actor, action, config, score, reasons)
    move_id = action["move_id"].to_s.upcase
    tags = Effects.describe(move_id, action["tags"])
    out_score = score
    target = target_for(snapshot, action["target"])
    actor_hp = Model.number(actor["hp_pct"], 100.0)
    target_hp = target ? Model.number(target["hp_pct"], 100.0) : 100.0
    # A spread move carries no registration target -- the adapter sets
    # action["target"] = nil because there is no single battler to register against
    # (Portable_AI_Adapter.rb:551) -- so target_for returns nil and this defaulted to a
    # phantom 100% target. Earthquake and Lava Plume therefore NEVER reached `lethal`,
    # at any target HP, and ko_never_lands could not fire for them either. The adapter
    # exports the scoring target's own HP on every action (:638); read that instead.
    if !target && config["spread_target_hp"] && !action["target_hp_pct"].nil?
      target_hp = Model.number(action["target_hp_pct"], 100.0)
    end
    damage = Model.number(action["expected_damage_pct"], 0.0)
    effectiveness = Model.number(action["effectiveness"], 1.0)

    if Model.truthy(action["immune"]) || (Model.truthy(action["damaging"]) && effectiveness <= 0)
      reasons << ["immune", HARD_REJECT]
      return HARD_REJECT
    end

    # A move the engine refused last turn against this same target will be refused
    # again: the board has not moved. Reborn keeps the flag itself for Stomping
    # Tantrum (PBEffects::Tantrum, PokeBattle_Battler.rb:5085) and the adapter reads it
    # back on the action. Bisharp clicked a dead Sucker Punch three turns running with
    # a guaranteed Knock Off KO one point behind (bulky_vs_offense 196613 t22-24), so
    # this is deliberately larger than that gap and smaller than a kill call.
    if config["move_memory"] && Model.truthy(action["failed_last_turn"])
      out_score -= 200
      reasons << ["failed_last_turn", -200]
    end

    lethal = false
    faster = faster_flag(actor)

    if Model.truthy(action["damaging"])
      lethal = damage >= target_hp && target_hp > 0

      # NOTE on Sturdy and Focus Sash. 0.5.0 first cancelled the kill call here --
      # lethal = false, damage := target_hp - 1 -- on the argument that a hit leaving
      # the target on 1 HP is not a knockout. It was WITHDRAWN before release, for
      # three reasons that are worth keeping written down:
      #
      #  * Reborn does not do it. Its notOHKO? (:17401) exists to pay a MULTI-HIT move
      #    x1.3 for beating the guard (:7389); it never removes a single-hit move's own
      #    kill score. The multi-hit row in side_effect_rules is that same fact, and it
      #    is what the corpus cards (sturdy_blocks_the_kill_call, focus_sash_same_as_
      #    sturdy, sash_ignored_when_not_full_hp) actually decide on -- none of them
      #    ever touched this block.
      #  * The cost was out of proportion to the information. Cancelling lethal takes
      #    about 420 points off the strongest move, which is far more than "you will
      #    need a second hit" is worth: hitting hard is still right, because breaking
      #    the guard is what makes the next hit lethal.
      #  * It measured badly and it is the only ability row that could. Of the six
      #    ability rows, Unaware, Contrary, Justified and Regenerator are all INERT on
      #    set_a..e (the gauntlet builds every mon with setAbility(0) and no roster mon
      #    carries them in slot 0), so ability_rules on those rosters was essentially
      #    this row plus the status-deterrent table -- and turning ability_rules off
      #    was worth +3 wins over 120 battles.
      #
      # The knowledge is still worth having for the priority gate and the heal gate,
      # which read `lethal`; reinstating it needs a form that does not also delete the
      # move's value, and a roster on which the rest of the table is not inert.
      priority = Model.number(action["priority"], 0)

      # A knockout only counts if it lands. When the actor is slower and the foe's
      # best move already kills it, a non-priority "KO" resolves after the actor is
      # gone, so it is worth its damage and nothing more (Reborn :2855-2923).
      if lethal && config["priority_gate"] && faster == false && priority <= 0 &&
         certain_lethal_threat?(actor, config)
        lethal = false
        reasons << ["ko_never_lands", 0]
      end

      if lethal
        value = 500.0
        out_score += value
        reasons << ["lethal", 500]
      elsif damage > 0
        value = [damage, 100.0].min * 0.8
        out_score += value
        reasons << ["expected_damage", value]
      else
        value = 0.0
      end

      # Reborn scales every move score by (accuracy + 100) / 200 (:3349), which is
      # what makes an accurate KO beat an inaccurate one -- Portable had no accuracy
      # term at all and over-clicked Fire Blast, Stone Edge and Focus Blast. Only the
      # damage terms are scaled; the type and tag rules keep their full weight.
      if value > 0
        factor = accuracy_factor(action, config)
        if factor != 1.0
          adjust = value * factor - value
          out_score += adjust
          reasons << ["accuracy", adjust]
        end
      end

      # Priority is worth most exactly where it is the only way the KO happens.
      if config["priority_gate"] && lethal && priority > 0 && !faster.nil?
        bonus = faster ? 60 : 150
        bonus += 200 if !faster && threatened_lethal?(actor)
        # A second foe acts whichever order this one resolves in, so moving first buys
        # much less: Reborn drops priority from x2 to x1.3 in doubles (:2856), and the
        # probe measured Aqua Jet at 242 in singles against 157 in the same doubles
        # position. Flat 60 rather than a scaled 150.
        if config["format_rules"] && doubles?(snapshot) && bonus > 60
          bonus = 60
          reasons << ["priority_flat_in_doubles", 0]
        end
        out_score += bonus
        reasons << ["priority_finisher", bonus]
      end

      # Once the move kills, the type chart has already said everything it has to say:
      # both kills remove the same battler, so the only thing left to choose on is
      # which one lands. Fire Blast at 85% was beating Dragon Claw at 100% for the same
      # KO on a 70-point super-effective bonus against a 45-point resist penalty
      # (bulky_vs_offense 196613 t4: 649 against 555). flat_kill also drops the
      # secondaries that only pay out on a survivor -- see side_effect_rules.
      #
      # NOT applied to a SPREAD action, which is a summary of several targets rather
      # than one kill: its damage is the sum over the foes and its effectiveness is a
      # standing measure of how much of the field the move resolves, which is exactly
      # what choose_joint weighs it against. Dropping the term there cost Garchomp a
      # double kill it had been finding since 0.4.0 -- d_spread_kills_both_preferred,
      # caught by the corpus on the first 0.6.2 probe (Earthquake 740 -> 600, and the
      # split-fire pair's coordination bonus then won by 66 points).
      flat_kill = lethal && config["lethal_flat"] && !Model.truthy(action["spread"])
      if flat_kill
        reasons << ["lethal_flat", 0]
      elsif effectiveness > 1
        bonus = 35 * effectiveness
        out_score += bonus
        reasons << ["super_effective", bonus]
      elsif effectiveness > 0 && effectiveness < 1
        out_score -= 45
        reasons << ["resisted", -45]
      end

      if config["side_effects"]
        out_score = side_effect_rules(snapshot, actor, action, tags, target,
                                      damage, lethal, faster, out_score, reasons,
                                      flat_kill)
      end
      if config["ability_rules"]
        out_score = damaging_ability_rules(action, target, lethal, out_score, reasons)
      end
    end

    if tags.include?("heal") || tags.include?("variable_heal")
      if actor_hp >= 85
        out_score -= 500
        reasons << ["heal_near_full", -500]
      elsif actor_hp <= 35
        bonus = 220 + (35 - actor_hp) * 3
        out_score += bonus
        reasons << ["heal_low_hp", bonus]
      elsif actor_hp <= 60
        out_score += 90
        reasons << ["heal_mid_hp", 90]
      end
      if config["heal_gate"]
        out_score = heal_gate(snapshot, actor, action, tags, out_score, reasons, config)
      elsif threatened_lethal?(actor)
        out_score -= 80
        reasons << ["heal_under_lethal_threat", -80]
      end
    elsif tags.include?("delayed_heal")
      # Wish fails outright with a Wish already pending (PokeBattle_MoveEffects.rb:6084
      # returns -1 and displays "But it failed!"). Same channel the screens use: the
      # adapter reports PBEffects::Wish through effect_active.
      if config["wish_pending"] && Model.truthy(action["effect_active"])
        out_score -= 300
        reasons << ["delayed_heal_pending", -300]
      elsif actor_hp >= 90
        out_score -= 300
        reasons << ["delayed_heal_near_full", -300]
      elsif actor_hp <= 55
        out_score += 100
        reasons << ["delayed_heal_useful", 100]
      end
    end

    if tags.include?("status")
      if target && occupied_status?(target["status"])
        out_score -= 450
        reasons << ["target_already_statused", -450]
      elsif target && Model.truthy(target["status_immune"])
        out_score -= 450
        reasons << ["target_status_immune", -450]
      else
        out_score += 25
        reasons << ["fresh_status", 25]
        if config["ability_rules"] && !Model.truthy(action["damaging"])
          out_score = status_deterrent_rule(action, tags, target, out_score, reasons)
        end
      end
    end

    if config["side_effects"]
      out_score = turn_shape_rules(snapshot, actor, action, tags, faster,
                                   out_score, reasons)
    end
    if config["format_rules"]
      out_score = format_rules(snapshot, actor, action, tags, out_score, reasons)
      return HARD_REJECT - 1 if out_score <= HARD_REJECT
    end

    if tags.include?("setup")
      repeats = config["memory"] ? memory_count(snapshot, actor["index"], "setup") : 0
      # The memory counter alone answers "did I set up on the PREVIOUS action", because
      # apply_memory zeroes every counter but the one it just incremented
      # (Portable_AI_Adapter.rb:1487). One attack in between and a +2 sweeper was
      # "first setting up" all over again -- Heracross took a second Swords Dance at
      # 31% HP that way (bulky_vs_offense 196613 t20). The stages the actor is standing
      # in are the durable record of the same fact, and one setup move is worth about
      # two stages (Swords Dance +2, Dragon Dance +1/+1, Calm Mind +1/+1).
      if config["setup_stage"]
        carried = Model.number(actor["positive_stage_total"], 0).to_i / 2
        repeats = carried if carried > repeats
      end
      if config["ability_rules"] && actor_ability(actor) == "CONTRARY"
        # Contrary turns every boost into a drop. Reborn does not have this row at all;
        # it is here because a Contrary user clicking Swords Dance is strictly harming
        # itself, which no amount of engine damage data reveals.
        out_score -= 300
        reasons << ["contrary_setup", -300]
      elsif config["ability_rules"] && target_fact(action, target, "ability") == "UNAWARE"
        # Boosting in front of Unaware achieves nothing: it reads through the stages.
        # Reborn halves the setup score (:4966); -150 is that halving in score units.
        out_score -= 150
        reasons << ["setup_vs_unaware", -150]
      elsif actor_hp <= 30 || threatened_lethal?(actor)
        out_score -= 240
        reasons << ["unsafe_setup", -240]
      elsif setup_into_2hko?(snapshot, actor, target, config)
        # Being 2HKOed while SLOWER means the boost never gets used: the foe's second
        # hit lands before the boosted attack does. Reborn charges x0.4 for exactly
        # this (:6007) on top of the x0.8/x0.3 a status move already pays; against a
        # ~450-point setup score that is about -180.
        #
        # The `faster == false` clause is NOT an inference from the source, it is a
        # measurement: on one board with +2 Speed and nothing else changed, stock
        # Reborn's Swords Dance went from 9 to 46 (PORTABLE-AI-REBORN.md, "0.6.0 Phase
        # A"). What refuses the setup there is the speed order, not the race, and a
        # faster mon setting up into a 2HKO is behaviour the reference endorses.
        #
        # Departure from the reference, recorded because a future agent comparing
        # against Reborn will otherwise read it as a bug: Reborn's gate also requires
        # `stats[PBStats::ATTACK]==1`, and `stats` holds STAGES, so its own rule
        # silently skips every +2 move (Swords Dance, Nasty Plot) and only ever
        # reaches +1 moves. That is a quirk of how the gate was written, not a claim
        # about play, so this rule applies to any setup tag.
        out_score -= 180
        reasons << ["setup_into_2hko", -180]
      elsif repeats == 0
        out_score += 55
        reasons << ["first_setup", 55]
      else
        penalty = 100 * repeats
        out_score -= penalty
        reasons << ["repeated_setup", -penalty]
      end
    end

    if tags.include?("hp_cost_half") && actor_hp <= 50
      out_score -= 600
      reasons << ["hp_cost_unaffordable", -600]
    end

    if config["self_cost"] && tags.include?("self_drop")
      if config["ability_rules"] && actor_ability(actor) == "CONTRARY"
        # The same ability read the other way round: Draco Meteor's -2 becomes +2, so
        # the move Portable is charged 40 for is the one a Contrary user wants most.
        out_score += 40
        reasons << ["contrary_boost", 40]
      else
        penalty = lethal ? 15 : 40
        out_score -= penalty
        reasons << ["self_stat_drop", -penalty]
      end
    end

    if config["self_cost"] && tags.include?("self_ko")
      # Fainting on purpose is a trade. It is not one with nothing left to send out --
      # the battle ends there -- and it is not one while healthy: Reborn's deathcode
      # (:7779) scales the score by 1 - hp% and lands at 0.14 at full HP, where
      # Portable exploded 15 times out of 21.
      reserves = Model.number(action["own_reserves"], 0)
      trade = reserves > 0 && (actor_hp < 30 || threatened_lethal?(actor))
      if !trade
        out_score -= 400
        reasons << ["self_ko_cost", -400]
      end
    end

    if tags.include?("charge_solar") && snapshot["weather"] != "sun"
      out_score -= 120
      reasons << ["charge_turn_without_sun", -120]
    end

    if tags.include?("force_switch")
      layers = Model.number(action["foe_hazard_layers"], 0)
      boosts = Model.number(action["target_positive_stages"], 0)
      bonus = layers * 15 + boosts * 25
      if bonus > 0
        out_score += bonus
        reasons << ["phaze_value", bonus]
      end
    end

    if tags.include?("protect") || tags.include?("team_protect")
      repeats = config["memory"] ? memory_count(snapshot, actor["index"], "protect") : 0
      if repeats > 0
        penalty = 140 * repeats
        out_score -= penalty
        reasons << ["repeated_protect", -penalty]
      end
    end

    if tags.include?("substitute")
      if actor_hp <= 25
        out_score -= 500
        reasons << ["cannot_afford_substitute", -500]
      elsif config["memory"] && memory_count(snapshot, actor["index"], "substitute") > 0
        out_score -= 250
        reasons << ["substitute_already_used", -250]
      end
    end

    if tags.include?("hazard")
      layers = Model.number(action["existing_layers"], 0).to_i
      maximum = Model.number(action["max_layers"], 1).to_i
      if layers >= maximum
        out_score -= 500
        reasons << ["hazard_at_cap", -500]
      elsif action.key?("hazard_targets") && Model.number(action["hazard_targets"], 0) <= 0
        out_score -= 600
        reasons << ["hazard_hits_nobody", -600]
      elsif Model.number(action["foe_reserves"], 0) <= 0
        out_score -= 180
        reasons << ["hazard_no_reserves", -180]
      end
    end

    if tags.include?("hazard_remove") && Model.number(action["own_hazard_layers"], 0) <= 0
      out_score -= 300
      reasons << ["no_hazards_to_remove", -300]
    end

    if tags.include?("screen") && Model.truthy(action["effect_active"])
      out_score -= 400
      reasons << ["screen_already_active", -400]
    end

    if tags.include?("baton_pass") && Model.number(action["own_reserves"], 0) <= 0
      out_score -= 600
      reasons << ["baton_pass_no_bench", -600]
    end

    # A non-damaging move aimed at the partner is hostile unless it is an actual
    # support move: statusing or disrupting your own side is never worth a turn.
    if Model.truthy(action["friendly_target"]) && !Model.truthy(action["damaging"]) &&
       !tags.include?("partner_support") && !tags.include?("redirect") &&
       !tags.include?("heal")
      reasons << ["hostile_move_at_partner", HARD_REJECT]
      return HARD_REJECT
    end

    friendly = Model.number(action["friendly_fire_pct"], 0.0)
    if friendly > 0
      if Model.truthy(action["friendly_target"])
        reasons << ["targeted_friendly_fire", HARD_REJECT]
        return HARD_REJECT
      end
      partner_hp = Model.number(action["partner_hp_pct"], 100.0)
      penalty = friendly * 3
      penalty += 700 if friendly >= partner_hp
      out_score -= penalty
      reasons << ["friendly_fire", -penalty]
    end

    if move_id == "THUNDER"
      if snapshot["weather"] == "rain"
        out_score += 100
        reasons << ["thunder_in_rain", 100]
      else
        out_score -= 100
        reasons << ["thunder_without_rain", -100]
      end
    end

    out_score
  end

  # Reasons that, on their own, justify leaving. Modelled on Reborn's
  # shouldSwitchintense? (PokeBattle_AI_2.rb:13713), which builds its switch score
  # purely from affirmative escape reasons — residual damage, its own debuffs, Yawn,
  # Perish Song — and never reads the opponent's stat stages. Deliberately excluded:
  # "matchup" and "engine_base" (type chart and HP, which are near-constant and were
  # the thing switching used to win on), and "preserve_low_hp_actor", which fires
  # exactly where Intense switches least — it never once switched below 30% HP across
  # 180 measured battles.
  # "escape_lethal_threat" opens the gate only above HEALTHY_PIVOT_HP_PCT.
  # threatened_lethal? is incoming_damage_pct >= hp_pct, which conflates two different
  # situations: a healthy battler facing a genuine hard counter (Garchomp into Lapras —
  # a real matchup problem, and a legitimate pivot the scenario corpus requires), and a
  # battler at 20% HP that everything threatens (not a matchup problem, just accumulated
  # damage). Counting both licensed exactly the switches this gate exists to stop: the
  # first gated run left switches-below-30%-HP unchanged at 2.09/battle. Intense treats
  # a weak battler as a reason to *stay* — shouldSwitchintense? subtracts 100 below 30%
  # HP for non-sweepers — and spends it attacking. Below the threshold the bonus still
  # applies once some other reason has opened the gate; it just cannot open it alone.
  HEALTHY_PIVOT_HP_PCT = 50

  # A boosted foe must not be able to open the gate by itself. A foe at +2 roughly
  # doubles its output, so it turns threatened_lethal? on without the matchup having
  # changed at all — and HEALTHY_PIVOT_HP_PCT then licenses the switch precisely when
  # the battler is healthy, which is the worst moment to leave: the switch-in eats a
  # free boosted hit and the boost is still there afterwards. Measured over 180 fair
  # baseline battles, Reborn-Normal switched 0 times out of 173 while the foe was at
  # >= +2, whereas 49 of Portable 0.3.0's 451 switches happened there — 10.9% of its
  # switching in 5.8% of its turns.
  #
  # Only the lethal-threat reason is suppressed. Every other escape reason (no
  # effective move, crushed stats, Yawn, residual chip) is a fact about this battler
  # that a foe's boosts did not manufacture, so a boosted foe does not veto those.
  BOOST_SUPPRESSES_LETHAL_ESCAPE = 2

  # Type-matchup units as the adapters hand them over: a single neutral verdict is 4 on
  # Reborn's chart and is scaled x8, so neutral lands on 32, resisted 16, immune 0,
  # super-effective 64 and doubly so 128. How hard the defensive term pulls against the
  # offensive one is the "switch_risk_weight" config key, defaulted in
  # Model::DEFAULT_CONFIG.
  NEUTRAL_TYPE_MATCHUP = 32

  SWITCH_ESCAPE_REASONS = %w[
    no_effective_move clear_crushed_stats clear_bad_stats weak_current_attacks
    escape_yawn escape_residual_chip escape_lethal_threat_while_healthy
    losing_damage_race
  ]

  # Highest positive stage total among the opposing active battlers.
  def self.foe_boost_total(snapshot)
    best = 0
    (snapshot["targets"] || []).each do |target|
      total = Model.number((target || {})["positive_stages"], 0)
      best = total if total > best
    end
    best
  end

  def self.score_switch(snapshot, actor, action, config, score, reasons)
    if !config["switching"] && !Model.truthy(action["forced"])
      reasons << ["switching_disabled", HARD_REJECT]
      return HARD_REJECT
    end

    out_score = score + Model.number(action["matchup_score"], 0)
    reasons << ["matchup", Model.number(action["matchup_score"], 0)]

    # "matchup" is offence only. Weigh what the incoming Pokemon will eat the same way,
    # symmetrically around neutral, so resisting the foe is worth as much as threatening
    # it and walking a Pokemon into a super-effective STAB costs what it should. Only
    # applies once a switch is happening; it never argues for or against leaving, just
    # for who goes in. Absent (older adapters, forced switches) it contributes nothing.
    weight = Model.number(config["switch_risk_weight"],
                          Model::DEFAULT_CONFIG["switch_risk_weight"])
    # When the adapter can estimate what the candidate ACTUALLY eats on the way in --
    # a real damage roll against a fake battler, with the candidate's own Intimidate
    # already applied to the foes -- that replaces the type proxy rather than joining
    # it. The proxy pays (32 - risk) * weight, so +32w for an immunity and -96w for a
    # 4x hit; 25% incoming is mapped to neutral and 100% to the 4x end, which puts the
    # real number on exactly the scale the rest of the switch score was tuned against.
    real_incoming = config["entry_rules"] && action.key?("incoming_damage_pct")
    if action.key?("incoming_risk") && weight != 0 && !real_incoming
      risk = Model.number(action["incoming_risk"], NEUTRAL_TYPE_MATCHUP)
      adjust = (NEUTRAL_TYPE_MATCHUP - risk) * weight
      out_score += adjust
      reasons << ["incoming_risk", adjust]
    elsif real_incoming && weight != 0
      incoming = Model.number(action["incoming_damage_pct"], 0.0)
      adjust = (25.0 - incoming) * 1.28 * weight
      out_score += adjust
      reasons << ["entry_incoming_damage", adjust]
    end

    # WHO COMES IN, rather than whether to leave -- so this is the one race consumer
    # that also applies to a forced switch, which is the post-KO replacement Radical
    # Red designed its table for (ANALYSIS.md :655-684). A candidate whose two damage
    # estimates the adapter could not build contributes nothing.
    #
    # Both halves are Reborn-measured, not guessed. Phase A put two identical
    # Mamoswine on the bench differing only in an Assault Vest -- one incoming number,
    # nothing else -- and stock scored them 257 against -175.8; two identical Ampharos
    # differing only in 252 Speed EVs scored 193 against 115.8, so outspeeding alone
    # is worth about +77 in Reborn's units (:11755-11764 scales a switch-in's damage
    # output x1.5 when it outruns the foe and x0.75 when it does not). Radical Red
    # pays a flat +14 for the same fact; scaled x5 into Portable's units -- where a
    # neutral matchup is 32 and one super-effective step is another 32 -- that is +70,
    # which is within rounding of what Reborn actually pays.
    if config["damage_race"] && action.key?("outgoing_damage_pct") &&
       action.key?("incoming_damage_pct")
      bonus = switchin_race_bonus(action)
      if bonus != 0
        out_score += bonus
        reasons << ["switchin_race", bonus]
      end
    end
    escapes = []

    if Model.truthy(action["forced"])
      out_score += 1000
      reasons << ["forced_switch", 1000]
    end
    if Model.truthy(actor["no_effective_move"])
      out_score += 260
      reasons << ["no_effective_move", 260]
      escapes << "no_effective_move"
    end
    negative_stages = Model.number(actor["negative_stage_total"], 0)
    if negative_stages <= -6
      bonus = [(-negative_stages) * 35, 350].min
      out_score += bonus
      reasons << ["clear_crushed_stats", bonus]
      escapes << "clear_crushed_stats"
    elsif negative_stages <= -3
      out_score += 90
      reasons << ["clear_bad_stats", 90]
      escapes << "clear_bad_stats"
    end
    if Model.number(actor["best_damage_pct"], 100) < 10
      out_score += 120
      reasons << ["weak_current_attacks", 120]
      escapes << "weak_current_attacks"
    end
    if Model.truthy(actor["yawned"])
      out_score += 300
      reasons << ["escape_yawn", 300]
      escapes << "escape_yawn"
    end
    residual = Model.number(actor["residual_damage_pct"], 0)
    if residual >= 20
      bonus = [residual * 8, 400].min
      out_score += bonus
      reasons << ["escape_residual_chip", bonus]
      escapes << "escape_residual_chip"
    end
    if Model.truthy(actor["trapped"])
      reasons << ["trapped", HARD_REJECT]
      return HARD_REJECT
    end
    if threatened_lethal?(actor)
      out_score += 130
      reasons << ["escape_lethal_threat", 130]
      boosted_foe = foe_boost_total(snapshot) >= BOOST_SUPPRESSES_LETHAL_ESCAPE
      reasons << ["boosted_foe_holds_ground", 0] if boosted_foe
      if !boosted_foe && Model.number(actor["hp_pct"], 100) >= HEALTHY_PIVOT_HP_PCT
        escapes << "escape_lethal_threat_while_healthy"
      end
    end

    # Losing the race by a whole turn, at full health, is the generalisation of
    # escape_lethal_threat_while_healthy from "it kills me in one" to "it kills me in
    # two". OFF BY DEFAULT, and that is a finding rather than caution: the Phase A
    # card race_leave_when_losing_2hko_vs_3hko put a healthy Donphan in front of an
    # Espeon that 2HKOs it with a Psychic-IMMUNE bench available, and stock Reborn's
    # shouldSwitch? came back -50 and never even scored the bench. So the reference
    # does not do this; it is Radical-Red-cited only, the switch programme was closed
    # on evidence (PORTABLE-AI-DIAGNOSIS.md §4), and it must not reopen by default.
    # The boost suppression is the same one escape_lethal_threat carries: a +2 foe
    # manufactures a losing race exactly the way it manufactures a lethal threat.
    if config["damage_race_switch"]
      race = worst_race(snapshot, actor, config)
      if !race.nil? && race["winning"] == false &&
         !race["theirs"].nil? && race["theirs"] <= 2 &&
         Model.number(actor["hp_pct"], 100) >= HEALTHY_PIVOT_HP_PCT &&
         foe_boost_total(snapshot) < BOOST_SUPPRESSES_LETHAL_ESCAPE
        out_score += 110
        reasons << ["losing_damage_race", 110]
        escapes << "losing_damage_race"
      end
    end
    if config["entry_rules"] && action.key?("entry_damage_pct")
      # The hazard charge is already inside engine_base; recorded as its own reason so
      # a trace can say how much of a switch's cost was the entry rather than the
      # candidate. Zero delta on purpose -- charging it twice was the alternative.
      reasons << ["entry_hazards", 0]
    end
    # Safe entry originally asked only whether the candidate cleared the hazards with
    # 20% to spare. What actually matters is whether it is still alive at the end of
    # the turn it comes in on, which needs the incoming hit as well.
    safe = Model.truthy(action["safe_entry"])
    if config["entry_rules"] && action.key?("entry_damage_pct") &&
       action.key?("incoming_damage_pct")
      safe = Model.number(action["candidate_hp_pct"], 100.0) -
             Model.number(action["entry_damage_pct"], 0.0) -
             Model.number(action["incoming_damage_pct"], 0.0) > 0
    end
    if Model.number(actor["hp_pct"], 100) <= 20 && safe
      out_score += 80
      reasons << ["preserve_low_hp_actor", 80]
    end
    # The same subtraction, read the other way: a candidate that is dead before it acts
    # is not a switch, it is a sacrifice, and score_switch computed this quantity for
    # `safe` without ever rejecting on it. Mandibuzz sent a 58-HP Flygon into Stealth
    # Rock plus a Rapid Spin; it died without moving and Mandibuzz walked back through
    # the rocks (bulky_vs_balance 196613 t51).
    #
    # Charged on the MINIMUM damage roll, so only a candidate that dies on every roll
    # pays, and charged rather than HARD_REJECTed so a forced replacement still ranks
    # the least bad body instead of falling through to slot order.
    #
    # 500, not the ~300 the backlog entry proposed, and the corpus is why: on
    # a_dying_switch_in_is_not_worth_sending the candidate scores 385.9 against a
    # 59.8 move, so 300 left the corpse ahead by 26 points and the card failed on the
    # build that was supposed to fix it. 500 is not a fitted number either -- it is
    # what this scorer already pays for a knockout, and handing the opponent a free one
    # is the same event seen from the other side.
    if config["entry_death"] && config["entry_rules"] &&
       action.key?("entry_damage_pct") && action.key?("incoming_damage_pct")
      left = Model.number(action["candidate_hp_pct"], 100.0) -
             Model.number(action["entry_damage_pct"], 0.0) -
             Model.number(action["incoming_damage_pct"], 0.0) * MIN_DAMAGE_ROLL
      if left <= 0
        out_score -= 500
        reasons << ["dies_on_entry", -500]
      end
    end
    if config["ability_rules"] && actor_ability(actor) == "REGENERATOR" &&
       Model.number(actor["hp_pct"], 100) < 66
      # Reborn INTENDS this (healscore += 40/50 at :13415 and :13792) but the guard is
      # `hp/totalhp < (2/3)`, and (2/3) is Ruby integer division = 0, so it has never
      # once fired. Implemented here as the intent, and deliberately NOT added to
      # SWITCH_ESCAPE_REASONS: regenerating is a discount on leaving, never a reason to.
      out_score += 50
      reasons << ["regenerator_pivot", 50]
    end
    if config["memory"] && memory_count(snapshot, actor["index"], "switch") > 1
      out_score -= 120
      reasons << ["switch_loop", -120]
    end

    # The gate. Without a named reason to leave, the switch is not considered at all,
    # so the actor falls through to its moves — the shape of Reborn Intense's
    # `next if shouldSwitchintense?` (PokeBattle_AI_2.rb:1571), rather than the
    # non-Intense `shouldswitchscore > maxmovescore` comparison at :1576.
    if config["switch_gate"] && escapes.empty? && !Model.truthy(action["forced"])
      reasons << ["no_escape_reason", HARD_REJECT]
      return HARD_REJECT
    end
    reasons << ["escape_reasons", escapes.length] if !escapes.empty?
    out_score
  end

  def self.choose_joint(snapshot, scored_by_actor, config)
    if scored_by_actor.length == 1 || !config["coordination"]
      return [scored_by_actor.map { |items| items[0] }, 0]
    end

    best_actions = nil
    best_score = nil
    best_adjustment = 0
    scored_by_actor[0].each do |left|
      scored_by_actor[1].each do |right|
        adjustment = joint_adjustment(snapshot, left, right)
        score = left["score"] + right["score"] + adjustment
        pair = [left, right]
        if best_score.nil? || score > best_score ||
           (score == best_score && pair_key(pair) < pair_key(best_actions))
          best_actions = pair
          best_score = score
          best_adjustment = adjustment
        end
      end
    end
    [best_actions, best_adjustment]
  end

  def self.joint_adjustment(snapshot, left, right)
    adjustment = 0
    if left["type"] == "switch" && right["type"] == "switch" &&
       left["slot"].to_i == right["slot"].to_i
      return HARD_REJECT
    end

    if single_target_move?(left) && single_target_move?(right) &&
       left["target"] == right["target"]
      target = target_for(snapshot, left["target"])
      hp = target ? Model.number(target["hp_pct"], 100) : 100
      dl = Model.number(left["expected_damage_pct"], 0)
      dr = Model.number(right["expected_damage_pct"], 0)
      if (dl >= hp || dr >= hp) && alternate_live_target?(snapshot, left["target"])
        adjustment -= 400
      elsif dl + dr > hp * 1.5 && alternate_live_target?(snapshot, left["target"])
        adjustment -= 180
      end
    elsif single_target_move?(left) && single_target_move?(right) &&
          left["target"] != right["target"]
      adjustment += 25
      [left, right].each do |action|
        target = target_for(snapshot, action["target"])
        if target && Model.number(target["hp_pct"], 100) <= 35
          quality = Model.number(action["effectiveness"], 1) * 100
          adjustment += quality
        end
      end
    end
    adjustment
  end

  def self.single_target_move?(action)
    return false if action.nil? || action["type"] != "move"
    !Model.truthy(action["spread"]) && !action["target"].nil?
  end

  def self.alternate_live_target?(snapshot, used_index)
    snapshot["targets"].any? do |target|
      target["index"] != used_index && Model.number(target["hp_pct"], 0) > 0
    end
  end

  def self.target_for(snapshot, index)
    return nil if index.nil?
    snapshot["targets"].each { |target| return target if target["index"] == index }
    snapshot["actors"].each { |actor| return actor if actor["index"] == index }
    nil
  end

  def self.occupied_status?(status)
    return false if status.nil? || status == 0 || status == "0"
    value = status.to_s.downcase
    value != "" && value != "none" && value != "healthy"
  end

  # pbRoughDamage is a single deterministic number, but the engine rolls 85-100% of it.
  # A rule that costs a move 400 points should only fire where no roll rescues the
  # battler, so "this hit kills me" is tested against the LOW roll rather than the
  # estimate. The estimate itself still answers the softer question of whether healing
  # might help (threatened_lethal?), which is what earns the bonus.
  MIN_DAMAGE_ROLL = 0.85

  # The incoming hit kills through any damage roll, not merely through the estimate.
  # threatened_lethal? is the softer question and stays what the 0.3.2 rules ask.
  def self.certain_lethal_threat?(actor, config = {})
    hp = Model.number(actor["hp_pct"], 100.0)
    return false if hp <= 0
    incoming = actor["incoming_damage_pct"]
    # Under strict_threat only a hit that cannot fail to happen (100% accurate, foe
    # awake) makes death certain; adapters that export no such figure keep the loose
    # one, so the key is inert where the evidence is missing.
    strict = actor["certain_incoming_damage_pct"]
    incoming = strict if config["strict_threat"] && !strict.nil?
    return Model.truthy(actor["threatened_lethal"]) if incoming.nil?
    Model.number(incoming, 0.0) * MIN_DAMAGE_ROLL >= hp
  end

  # Tri-state speed order: true, false, or nil when the adapter exports none. Rules
  # that would cost the actor points treat nil as "faster", so a missing field never
  # penalises it; the priority gate skips itself entirely instead.
  def self.faster_flag(actor)
    value = actor["faster"]
    return nil if value.nil?
    Model.truthy(value)
  end

  # Reborn's (accuracy + 100) / 200 (PokeBattle_AI_2.rb:3349), softened by
  # config["accuracy_weight"] so 0 reproduces 0.3.2 and 1 is Reborn's own weight.
  # Adapters that export no accuracy contribute nothing.
  def self.accuracy_factor(action, config)
    weight = Model.number(config["accuracy_weight"],
                          Model::DEFAULT_CONFIG["accuracy_weight"])
    return 1.0 if weight == 0
    return 1.0 if !action.key?("accuracy") || action["accuracy"].nil?
    accuracy = Model.number(action["accuracy"], 100.0)
    accuracy = 100.0 if accuracy > 100.0
    accuracy = 0.0 if accuracy < 0
    1.0 + (((accuracy + 100.0) / 200.0) - 1.0) * weight
  end

  # Percentage points of maximum HP a recovery move restores, in the same units as
  # hp_pct and incoming_damage_pct.
  def self.heal_amount(snapshot, tags)
    return 100.0 if tags.include?("heal_full")
    if tags.include?("heal_weather")
      weather = snapshot["weather"]
      return 66.0 if weather == "sun"
      return 25.0 if weather == "sand" || weather == "hail"
    end
    50.0
  end

  # Does healing change who is alive at the end of the turn? Reborn's recovercode
  # (PokeBattle_AI_2.rb:7558) asks that; Portable 0.3.2 scored recovery on the healer's
  # own HP alone, which is why a quarter of its heals were the healer's last act and
  # 61% of the ones below 25% HP were (PORTABLE-AI-DIAGNOSIS.md section 2). These are
  # Reborn's multipliers rewritten as additive score units, plus the question Reborn
  # never asks -- whether it moves first -- which costs Reborn 18% of its own slow
  # heals. The existing hp_pct bonuses stay underneath: this rule only fires when the
  # actor is actually being threatened, so the plain low-HP heal is untouched.
  def self.heal_gate(snapshot, actor, action, tags, score, reasons, config = {})
    hp = Model.number(actor["hp_pct"], 100.0)
    incoming = Model.number(actor["incoming_damage_pct"], 0.0)
    # threatened_lethal is the adapter's own verdict; honour it when the raw number is
    # absent or disagrees.
    incoming = hp if Model.truthy(actor["threatened_lethal"]) && incoming < hp
    heal = heal_amount(snapshot, tags)
    headroom = 100.0 - hp
    heal = headroom if heal > headroom
    heal = 0.0 if heal < 0
    faster = faster_flag(actor)
    # Penalise only what no damage roll can rescue; reward wherever the heal might be
    # what survives the turn.
    will_die = certain_lethal_threat?(actor, config)
    might_die = threatened_lethal?(actor)

    if will_die && faster == false
      score -= 400
      reasons << ["heal_cannot_resolve", -400]
    elsif will_die && incoming * MIN_DAMAGE_ROLL >= hp + heal
      score -= 400
      reasons << ["heal_does_not_save", -400]
    elsif might_die
      score += 150
      reasons << ["heal_saves_battler", 150]
    elsif incoming > heal
      score -= 120
      reasons << ["heal_losing_race", -120]
    end

    # Reborn's x0.3 when the foe is on its last Pokemon and a KO is in hand: there is
    # nothing left to outlast.
    if Model.number(action["foe_reserves"], 1) <= 0 && has_lethal_move?(snapshot, actor)
      score -= 200
      reasons << ["finish_instead_of_heal", -200]
    end
    score
  end

  # Every damaging action of this actor that can actually land, with the target each
  # one is scored against. has_lethal_move? and damage_race must agree on what counts
  # as "a hit on that target", so the matching lives here once. A spread move and a
  # single-foe snapshot's untargeted move both count against whichever target is asked
  # about, which is the same latitude has_lethal_move? has always taken.
  def self.each_damaging_action(snapshot, actor, only_target = nil)
    (actor["actions"] || []).each do |other|
      next if other["type"] != "move"
      next if !Model.truthy(other["damaging"]) || Model.truthy(other["immune"])
      next if Model.number(other["effectiveness"], 1.0) <= 0
      target = target_for(snapshot, other["target"])
      if !only_target.nil?
        aimed = (other["target"] == only_target["index"]) ||
                Model.truthy(other["spread"]) ||
                (other["target"].nil? && (snapshot["targets"] || []).length <= 1)
        next if !aimed
        target = only_target
      end
      target_hp = target ? Model.number(target["hp_pct"], 100.0) :
                           Model.number(other["target_hp_pct"], 100.0)
      next if target_hp <= 0
      yield other, target, target_hp
    end
  end

  def self.has_lethal_move?(snapshot, actor)
    each_damaging_action(snapshot, actor) do |other, _target, target_hp|
      return true if Model.number(other["expected_damage_pct"], 0.0) >= target_hp
    end
    false
  end

  # Beyond this many hits the exchange is not a race any more, it is a stall war, and
  # the counts stop carrying information. Cap rather than let a chip move produce a
  # 40-turn "plan" that compares equal to another one.
  RACE_MAX_HITS = 8

  # HOW MANY HITS EACH SIDE NEEDS, AND WHO LANDS THE LAST ONE.
  #
  # Every other rule in this core asks a one-hit question -- does the next hit kill me,
  # does my next hit kill it. This is the two-hit question a bulky team plays by.
  # Reborn has no explicit hits-to-KO either, but `maxdam*2 > hp` gates its setup
  # (PokeBattle_AI_2.rb:6007), its recovery (:7588) and Rest (:7667), hpGainPerTurn
  # (:10112) folds residual into the same comparison, and pbAIfaster? (:10051) orders
  # the final hit per move PAIR -- so a priority move on either side rewrites who lands
  # last. Radical Red states the same thing in five lines (ANALYSIS.md :655-684).
  #
  # Pure: it reads the snapshot and nothing else, so the adapter can call it on a
  # snapshot it has just built (view_trace does exactly that). Returns nil the moment
  # an input is missing -- an adapter with no threats_by_foe, an actor with no damaging
  # move -- and every consumer is written to go inert on nil. That is the same "a
  # missing field never penalises the actor" contract as faster_flag.
  #
  # Point estimates, not low rolls. The race is the soft question, the way
  # threatened_lethal? is; the consumers only ever withhold a bonus or add an escape
  # reason, never a -400. Accuracy is deliberately ignored, as Reborn's maxdam ignores
  # it too.
  def self.damage_race(snapshot, actor, target, config)
    return nil if !config["damage_race"] || actor.nil? || target.nil?

    target_hp = Model.number(target["hp_pct"], 100.0)
    actor_hp = Model.number(actor["hp_pct"], 100.0)
    return nil if target_hp <= 0 || actor_hp <= 0

    mine_best = 0.0
    mine_priority = 0.0
    guard = false
    each_damaging_action(snapshot, actor, target) do |other, target_view, _hp|
      damage = Model.number(other["expected_damage_pct"], 0.0)
      next if damage <= 0
      mine_best = damage if damage > mine_best
      guard = true if one_hit_guard?(other, target_view) && damage >= target_hp
      mine_priority = damage if Model.number(other["priority"], 0) > 0 &&
                                damage > mine_priority
    end

    # A race needs both sides. With no hit of my own on this target there is no
    # hit-count question to answer, and the rules that already cover that position
    # (no_effective_move, weak_current_attacks) are the ones that should speak.
    return nil if mine_best <= 0

    threats = actor["threats_by_foe"]
    return nil if threats.nil?
    threat = threats[target["index"].to_s] || threats[target["index"]]
    return nil if threat.nil?
    theirs_best = Model.number(threat["damage_pct"], 0.0)
    theirs_priority = Model.number(threat["priority_damage_pct"], 0.0)
    faster = threat["faster"]
    faster = nil if faster != true && faster != false

    # Sturdy and Focus Sash do not reduce the hit, they cost a whole extra one: the
    # blow that would have killed leaves the target on 1 HP. This is the ONE place the
    # guard belongs -- 0.5.0 deliberately left the kill call alone (see the note in
    # score_move), because cancelling `lethal` deletes the move's value, whereas
    # spending a hit is exactly what the guard actually does.
    mine = hits_needed(target_hp, mine_best)
    mine += 1 if !mine.nil? && guard && mine < RACE_MAX_HITS

    # Residual is on MY side only: the actor's own toxic and leech are exported, the
    # foe's are not. Reborn's hpGainPerTurn is the same one-sided term.
    residual = Model.number(actor["residual_damage_pct"], 0.0)
    theirs = hits_needed(actor_hp, theirs_best + residual)

    winning = nil
    last_hit_first = nil
    if !mine.nil? && !theirs.nil?
      if mine < theirs
        # A hit-count gap cannot be closed by speed or priority: the side needing
        # fewer hits simply finishes on an earlier turn.
        winning = true
      elsif mine > theirs
        winning = false
      else
        # Equal counts, so the exchange is decided by who lands the FINAL hit. This is
        # pbAIfaster?(attackermove, opponentmove) restricted to the last exchange: a
        # priority move only decides it if it is big enough to finish the job.
        mine_finishes = mine_priority > 0 &&
                        mine_priority >= target_hp - (mine - 1) * mine_best
        theirs_finishes = theirs_priority > 0 &&
                          theirs_priority >= actor_hp - (theirs - 1) * (theirs_best + residual)
        if mine_finishes && !theirs_finishes
          last_hit_first = true
        elsif theirs_finishes && !mine_finishes
          last_hit_first = false
        else
          last_hit_first = faster
        end
        winning = last_hit_first if !last_hit_first.nil?
      end
    end

    { "mine" => mine, "theirs" => theirs, "faster" => faster,
      "last_hit_first" => last_hit_first, "winning" => winning }
  end

  # nil when nothing gets through, otherwise the capped number of hits.
  def self.hits_needed(hp, per_hit)
    return nil if per_hit.nil? || per_hit <= 0
    count = (hp / per_hit.to_f).ceil
    count = RACE_MAX_HITS if count > RACE_MAX_HITS
    count = 1 if count < 1
    count
  end


  # "The foe kills me in two and I do not move first." Silent -- false, never a
  # penalty -- whenever the race is unavailable.
  # The race against whichever current foe the actor is doing worst against. In
  # singles that is the only foe; in doubles, losing to either one is a reason to
  # leave. nil when no target yields a race at all.
  # Radical Red's switch-in table, scaled x5 into Portable's switch units. The bands
  # are hits the FOE needs to knock this candidate out; the +70 is for outrunning it.
  # Keyed off the candidate's own HP, not 100%, because a chipped bench mon that dies
  # in one is exactly the candidate this is meant to refuse.
  # Radical Red's switch-in table, scaled x5 into Portable's switch units (a neutral
  # matchup is 32 there, and one super-effective step is another 32). The bands are
  # how many hits the FOE needs to knock this candidate out.
  SWITCHIN_RACE_OUTSPEED = 70

  def self.switchin_race_bonus(action)
    # The candidate's OWN hp, not 100: a chipped bench mon that dies in one is exactly
    # the candidate this is here to refuse.
    hp = Model.number(action["candidate_hp_pct"], 100.0)
    hp = 100.0 if hp <= 0
    theirs = hits_needed(hp, Model.number(action["incoming_damage_pct"], 0.0))
    bonus = 0
    if theirs.nil? || theirs >= 4
      bonus += 85            # nothing the foe has gets through in a hurry
    elsif theirs == 3
      bonus += 10
    elsif theirs == 2
      bonus -= 5
    else
      bonus -= 70            # it dies on the turn it arrives
    end
    # Reborn scales a switch-in's damage OUTPUT by whether it outruns the foe
    # (:11755-11764, x1.5 against x0.75), so the premium belongs to a candidate that
    # has output to scale. One that deals nothing gains nothing by moving first.
    if action["faster"] == true &&
       Model.number(action["outgoing_damage_pct"], 0.0) > 0
      bonus += SWITCHIN_RACE_OUTSPEED
    end
    bonus
  end

  def self.worst_race(snapshot, actor, config)
    worst = nil
    (snapshot["targets"] || []).each do |target|
      race = damage_race(snapshot, actor, target, config)
      next if race.nil?
      worst = race if worst.nil? || race_rank(race) < race_rank(worst)
    end
    worst
  end

  # Lower is worse for the actor: losing < unknown < winning, and within losing the
  # one that kills it soonest.
  def self.race_rank(race)
    base = if race["winning"] == false then 0
           elsif race["winning"].nil? then 1
           else 2
           end
    theirs = race["theirs"].nil? ? RACE_MAX_HITS : race["theirs"]
    base * 100 + theirs
  end

  # A setup move is a STATUS move and the adapter gives it no scoring target, so
  # `target` is nil here in singles as well as doubles. Fall back to the foe the actor
  # is doing worst against, which is the one the setup has to survive. This cost a
  # portable probe run: the rule was silently inert on every card until the nil-target
  # case was found, and the unit test had been written with a target on the setup move.
  def self.setup_into_2hko?(snapshot, actor, target, config)
    race = target.nil? ? worst_race(snapshot, actor, config) :
                         damage_race(snapshot, actor, target, config)
    return false if race.nil?
    theirs = race["theirs"]
    return false if theirs.nil? || theirs > 2
    race["faster"] == false
  end

  def self.threatened_lethal?(actor)
    Model.truthy(actor["threatened_lethal"]) ||
      Model.number(actor["incoming_damage_pct"], 0) >= Model.number(actor["hp_pct"], 100)
  end

  def self.memory_count(snapshot, actor_index, key)
    memory = snapshot["memory"] || {}
    actor = memory[actor_index.to_s] || memory[actor_index] || {}
    Model.number(actor[key], 0).to_i
  end

  def self.memory_updates(actions)
    out = {}
    actions.each do |action|
      actor_index = action["actor_index"]
      update = { "last_type" => action["type"] }
      if action["type"] == "switch"
        update["increment"] = "switch"
      else
        tags = Effects.describe(action["move_id"], action["tags"])
        update["last_move"] = action["move_id"]
        if tags.include?("setup")
          update["increment"] = "setup"
        elsif tags.include?("protect") || tags.include?("team_protect")
          update["increment"] = "protect"
        elsif tags.include?("substitute")
          update["increment"] = "substitute"
        end
      end
      out[actor_index.to_s] = update
    end
    out
  end

  # ---------------------------------------------------------------------------
  # 0.5.0 tables.
  #
  # Reborn multiplies a move's damage-percent score by a per-move `miniscore`;
  # Portable adds. The quantity that multiplier scales is the move's DAMAGE score,
  # which here is the flat lethal bonus when the move kills and the capped damage term
  # when it does not — so scaling that same quantity keeps a x0.9 recoil charge worth
  # a tenth of what the move is actually being clicked for, instead of a tenth of a
  # number that stops mattering the moment the move is lethal.
  # ---------------------------------------------------------------------------
  def self.damage_value(lethal, damage)
    return 500.0 if lethal
    [Model.number(damage, 0.0), 100.0].min * 0.8
  end

  def self.multiplier_delta(m, lethal, damage)
    (m - 1.0) * damage_value(lethal, damage)
  end

  # Reborn's pbReduceWhenKills (:9887): once the damage score is at the cap, the
  # multiplier is square-rooted. x1.68 becomes x1.30 and x0.9 becomes x0.95 — bonuses
  # and costs soften alike, because by then the move is being clicked for the knockout
  # and not for what it does afterwards.
  def self.reduce_when_kills(m, lethal)
    return m if !lethal || m <= 0
    Math.sqrt(m)
  end

  # A secondary that fires 30% of the time is worth 30% of the effect. Reborn does NOT
  # do this — burncode/paracode/poisoncode/freezecode never read the move's addlEffect,
  # so Scald's 30% burn and Will-O-Wisp's 100% burn are priced identically (measured,
  # PORTABLE-AI-REBORN.md "0.5.0 Phase A", finding 6). This is a deliberate DEPARTURE.
  # A chance of exactly 0 means the effect is negated outright (Sheer Force, Shield
  # Dust, Covert Cloak) and the whole row is skipped by the caller.
  def self.chance_scaled(m, chance)
    return m if chance.nil?
    fraction = Model.number(chance, 100.0) / 100.0
    fraction = 1.0 if fraction > 1.0
    1.0 + (m - 1.0) * fraction
  end

  # Fact about the move's target, from the target view when the snapshot carries one
  # and from the action otherwise. Spread moves have no single target and read the
  # action's copy; unit tests may use either.
  def self.target_fact(action, target, key)
    return target[key] if target && !target[key].nil?
    action["target_" + key]
  end

  def self.actor_ability(actor)
    value = (actor || {})["ability"]
    value.nil? ? nil : value.to_s.upcase
  end

  def self.doubles?(snapshot)
    return true if (snapshot["format"] || "").to_s == "double"
    (snapshot["actors"] || []).length > 1
  end

  # Sturdy and Focus Sash both mean "survives one hit from full HP". Mold Breaker turns
  # Sturdy off and a multi-hit move beats both, which is exactly Reborn's notOHKO?
  # (:17401-17409) minus the field- and form-specific rows.
  # Sturdy, or a Focus Sash, on a full-HP target: it survives one hit whatever that
  # hit was. Mold Breaker turns Sturdy off. Read by the multi-hit row, which is the
  # only place 0.5.0 prices it -- see the note in score_move.
  def self.one_hit_guard?(action, target)
    return false if !Model.truthy(target_fact(action, target, "full_hp"))
    item = (target_fact(action, target, "item") || "").to_s.upcase
    return true if item == "FOCUSSASH"
    ability = (target_fact(action, target, "ability") || "").to_s.upcase
    ability == "STURDY" && !Model.truthy(action["mold_breaker"])
  end

  # Abilities the TARGET has that make a status worth less, keyed by status kind.
  # Copied from Reborn's burncode (:5647), paracode (:5605) and poisoncode, which is
  # where the numbers come from; nothing here is invented.
  STATUS_DETERRENTS = {
    "burn" => { "GUTS" => 0.1, "FLAREBOOST" => 0.1, "QUICKFEET" => 0.3,
                "NATURALCURE" => 0.3, "MAGICGUARD" => 0.5, "SYNCHRONIZE" => 0.5,
                "MARVELSCALE" => 0.7, "SHEDSKIN" => 0.7, "WATERVEIL" => 0.0 },
    "poison" => { "POISONHEAL" => 0.1, "MAGICGUARD" => 0.1, "TOXICBOOST" => 0.2,
                  "GUTS" => 0.2, "QUICKFEET" => 0.3, "NATURALCURE" => 0.3,
                  "SYNCHRONIZE" => 0.5, "SHEDSKIN" => 0.7, "IMMUNITY" => 0.0 },
    "paralyze" => { "GUTS" => 0.2, "QUICKFEET" => 0.2, "NATURALCURE" => 0.3,
                    "MARVELSCALE" => 0.5, "SYNCHRONIZE" => 0.5, "SHEDSKIN" => 0.7,
                    "LIMBER" => 0.0 },
    "freeze" => { "NATURALCURE" => 0.3, "SYNCHRONIZE" => 0.5, "MARVELSCALE" => 0.8,
                  "MAGMAARMOR" => 0.0 },
    "sleep" => { "NATURALCURE" => 0.3, "SHEDSKIN" => 0.7, "EARLYBIRD" => 0.5,
                 "INSOMNIA" => 0.0, "VITALSPIRIT" => 0.0 }
  }

  STATUS_KINDS = %w[burn poison paralyze freeze sleep confuse]

  def self.status_kind(tags)
    STATUS_KINDS.each { |kind| return kind if tags.include?(kind) }
    nil
  end

  def self.status_deterrent(kind, ability)
    return 1.0 if kind.nil? || ability.nil?
    row = STATUS_DETERRENTS[kind]
    return 1.0 if !row
    value = row[ability.to_s.upcase]
    value.nil? ? 1.0 : value
  end

  # A pure status move aimed at a target that profits from the status. Reborn's own
  # multipliers, restated: at x0.3 or worse the move is a mistake rather than merely a
  # weak choice, so the flat +25 the status block just paid becomes -150.
  def self.status_deterrent_rule(action, tags, target, score, reasons)
    m = status_deterrent(status_kind(tags), target_fact(action, target, "ability"))
    return score if m >= 1.0
    if m <= 0.3
      score -= 175
      reasons << ["status_deterred", -175]
    else
      penalty = (1.0 - m) * 100.0
      score -= penalty
      reasons << ["status_deterred", -penalty]
    end
    score
  end

  # Item removal is worth what the item was worth. Reborn's knockcode (:8072) is a
  # short whitelist and returns a flat 1 for everything else -- including Focus Sash,
  # which a human would certainly rather remove. Copied as-is rather than extended:
  # the probe measured Knock Off at 75 / 58 / 39 against Leftovers / Sash / no item,
  # and the 58 is the ENGINE's own x1.5 damage boost against an item holder, which
  # reaches the core through expected_damage_pct without any rule's help.
  ITEM_REMOVAL_VALUE = {
    "LEFTOVERS" => 1.3, "BLACKSLUDGE" => 1.3,
    "LIFEORB" => 1.2, "CHOICESCARF" => 1.2, "CHOICEBAND" => 1.2,
    "CHOICESPECS" => 1.2, "ASSAULTVEST" => 1.2
  }

  CONTACT_PUNISHERS = %w[ROUGHSKIN IRONBARBS UNBREAKABLEBODY]

  ABSORB_ABILITIES = {
    "FLASHFIRE" => "FIRE", "WELLBAKEDBODY" => "FIRE",
    "WATERABSORB" => "WATER", "STORMDRAIN" => "WATER", "DRYSKIN" => "WATER",
    "SAPSIPPER" => "GRASS", "EARTHEATER" => "GROUND",
    "VOLTABSORB" => "ELECTRIC", "LIGHTNINGROD" => "ELECTRIC",
    "MOTORDRIVE" => "ELECTRIC", "JUSTIFIED" => "DARK"
  }

  REDIRECT_ABILITIES = { "LIGHTNINGROD" => "ELECTRIC", "STORMDRAIN" => "WATER" }

  # Every per-move side effect that scales the damage the move already does. One pass,
  # one named reason per row that fires, so a trace says which table entry moved the
  # score.
  # flat_kill (0.6.2, config["lethal_flat"]) drops the rows that only pay out if the
  # target is still standing afterwards -- the secondary status/flinch/stat-drop, and
  # the knocked item. The rows that survive it are the ones about whether the knockout
  # HAPPENS or what it costs the actor: multi_hit versus Sturdy/Sash, recoil, drain.
  def self.side_effect_rules(snapshot, actor, action, tags, target, damage,
                             lethal, faster, score, reasons, flat_kill = false)
    chance = action.key?("effect_chance") ? Model.number(action["effect_chance"], 100.0) : nil
    kind = action["effect_kind"]
    kind = Effects.kind_of(tags, "secondary") if kind.nil?
    kind = kind.nil? ? nil : kind.to_s
    target_ability = (target_fact(action, target, "ability") || "").to_s.upcase
    target_item = (target_fact(action, target, "item") || "").to_s.upcase

    # chance == 0 is the engine saying the secondary is negated outright (Sheer Force,
    # Shield Dust, Covert Cloak). No row fires, and the move is judged on damage alone.
    if kind && !(chance && chance <= 0) && !flat_kill
      m = secondary_multiplier(kind, action, actor, target, target_ability,
                               lethal, faster)
      if m != 1.0
        m = chance_scaled(m, chance)
        m = reduce_when_kills(m, lethal)
        delta = multiplier_delta(m, lethal, damage)
        if delta != 0
          # A status the target profits from is a reason NOT to click the move, and the
          # deterrent table is the same one the pure status moves use.
          score += delta
          reasons << ["secondary_" + kind, delta]
        end
      end
    end

    if Model.truthy(action["multi_hit"])
      m = 1.0
      m *= 1.3 if one_hit_guard?(action, target)
      if Model.truthy(action["contact"]) &&
         (CONTACT_PUNISHERS.include?(target_ability) || target_item == "ROCKYHELMET")
        m *= 0.7
      end
      if m != 1.0
        delta = multiplier_delta(reduce_when_kills(m, lethal), lethal, damage)
        score += delta
        reasons << ["multi_hit", delta]
      end
    end

    recoil = Model.number(action["recoil_fraction"], 0.0)
    if recoil > 0 && actor_ability(actor) != "ROCKHEAD" && actor_ability(actor) != "MAGICGUARD"
      hp = Model.number(actor["hp_pct"], 100.0)
      m = 0.9
      m *= 0.8 if hp > 10 && hp < 40
      delta = multiplier_delta(reduce_when_kills(m, lethal), lethal, damage)
      score += delta
      reasons << ["recoil_cost", delta]
    end

    drain = Model.number(action["drain_fraction"], 0.0)
    if drain > 0
      hp = Model.number(actor["hp_pct"], 100.0)
      missing = 100.0 - hp
      if missing <= 0 && faster == true
        # Nothing to restore and the drain resolves after the hit either way
        # (absorbcode's guard clause, :7742).
      else
        healed = [Model.number(damage, 0.0) * drain, missing].min
        m = 1.0 + 0.5 * healed / 100.0
        m = 2.0 - m if target_ability == "LIQUIDOOZE"
        delta = multiplier_delta(reduce_when_kills(m, lethal), lethal, damage)
        if delta != 0
          score += delta
          reasons << ["drain_heal", delta]
        end
      end
    end

    if tags.include?("item_removal") && target_item != "" && !flat_kill
      m = ITEM_REMOVAL_VALUE[target_item] || 1.0
      if m != 1.0
        delta = multiplier_delta(reduce_when_kills(m, lethal), lethal, damage)
        score += delta
        reasons << ["knocks_item", delta]
      end
    end
    score
  end

  # The per-kind multiplier before chance and the kill reduction are applied.
  def self.secondary_multiplier(kind, action, actor, target, target_ability,
                                lethal, faster)
    deterrent = status_deterrent(kind, target_ability)
    case kind
    when "burn"
      m = 1.2
      m *= 1.4 if Model.truthy(target_fact(action, target, "physical_attacker"))
      m * deterrent
    when "poison", "freeze", "sleep"
      1.2 * deterrent
    when "paralyze"
      m = 1.0
      # Worth something only where halving the target's Speed changes who moves first.
      if faster == false
        target_speed = Model.number(target_fact(action, target, "speed"), 0.0)
        actor_speed = Model.number(actor["speed"], 0.0)
        m *= 1.2 if target_speed > 0 && actor_speed > 0 && target_speed / 2.0 < actor_speed
      end
      m *= 1.1 if Model.truthy(target_fact(action, target, "special_attacker"))
      m * deterrent
    when "flinch"
      # A flinch you never inflict is worth nothing: Reborn returns a flat 1 when the
      # user is slower or the move already kills (:5691).
      return 1.0 if faster != true || lethal
      return 1.0 if target_ability == "INNERFOCUS" || target_ability == "SHIELDDUST"
      return 1.0 if Model.truthy(target_fact(action, target, "substitute"))
      1.3
    when "drop"
      stat = (action["effect_stat"] || "").to_s.downcase
      return 1.0 if target_ability == "CLEARBODY" || target_ability == "WHITESMOKE" ||
                    target_ability == "FULLMETALBODY" || target_ability == "GOODASGOLD"
      case stat
      when "speed"
        faster == false ? 1.3 : 1.0
      when "spa"
        Model.truthy(target_fact(action, target, "special_attacker")) ? 1.2 : 1.0
      when "atk"
        Model.truthy(target_fact(action, target, "physical_attacker")) ? 1.2 : 1.0
      when "def", "spd"
        lethal ? 1.0 : 1.1
      else
        1.0
      end
    else
      1.0
    end
  end

  # Rules about what a move does to the SHAPE of the turn rather than to its damage:
  # speed control, first-turn-only moves, delayed damage. Flat score units, because
  # none of these three is a multiplier on damage the move does now.
  def self.turn_shape_rules(snapshot, actor, action, tags, faster, score, reasons)
    if tags.include?("first_turn_only")
      if Model.number(actor["turncount"], 0) == 0
        score += 115
        reasons << ["first_turn_hit", 115]
      else
        reasons << ["first_turn_over", HARD_REJECT]
        return HARD_REJECT
      end
    end

    if tags.include?("delayed_damage")
      if Model.truthy(action["effect_active"])
        score -= 200
        reasons << ["delayed_damage_pending", -200]
      elsif !threatened_lethal?(actor)
        score += 40
        reasons << ["delayed_damage", 40]
      end
    end

    if tags.include?("field_speed")
      move_id = action["move_id"].to_s.upcase
      active = move_id == "TRICKROOM" ? Model.truthy(snapshot["trick_room_active"]) :
                                        Model.truthy(snapshot["tailwind_active"])
      if active
        score -= 500
        reasons << ["speed_control_redundant", -500]
      elsif faster == false
        bonus = move_id == "TRICKROOM" ? 120 : 80
        # Trick Room is a whole-team investment: it is only worth a turn if the bench
        # is slow too, otherwise it hurts the mons that come in after this one.
        if move_id == "TRICKROOM"
          bench = Model.number(actor["slower_bench_count"], -1)
          reserves = Model.number(action["own_reserves"], 0)
          if bench >= 0 && reserves > 0 && bench * 2 < reserves
            bonus = 0
            reasons << ["trick_room_bench_is_fast", 0]
          end
        end
        bonus = (bonus * 1.3).round if bonus > 0 && doubles?(snapshot)
        if bonus > 0
          score += bonus
          reasons << ["speed_control_value", bonus]
        end
      end
    end
    score
  end

  # Doubles-only. Everything here is inert in singles except partner_heal, which is a
  # dead move there and says so.
  def self.format_rules(snapshot, actor, action, tags, score, reasons)
    if tags.include?("partner_heal")
      if !doubles?(snapshot)
        reasons << ["partner_heal_in_singles", HARD_REJECT]
        return HARD_REJECT
      end
      partner_hp = Model.number(actor["partner_hp_pct"], 100.0)
      if !Model.truthy(actor["partner_alive"])
        reasons << ["partner_heal_no_partner", HARD_REJECT]
        return HARD_REJECT
      elsif partner_hp >= 85
        score -= 500
        reasons << ["partner_heal_near_full", -500]
      elsif partner_hp <= 35
        bonus = 220 + (35 - partner_hp) * 3
        score += bonus
        reasons << ["partner_heal_low_hp", bonus]
      elsif partner_hp <= 60
        score += 90
        reasons << ["partner_heal_mid_hp", 90]
      end
    end
    return score if !doubles?(snapshot)

    move_type = (action["move_type"] || "").to_s.upcase
    return score if move_type == ""
    damage = Model.number(action["expected_damage_pct"], 0.0)

    if Model.truthy(action["spread"]) && Model.truthy(actor["partner_alive"])
      partner_ability = (actor["partner_ability"] || "").to_s.upcase
      if ABSORB_ABILITIES[partner_ability] == move_type
        # The partner does not merely survive the spread move, it profits from it:
        # Reborn doubles the score (:2031) and the probe measured Discharge at 280
        # against Thunderbolt's 112 on exactly that board.
        delta = multiplier_delta(2.0, false, damage)
        score += delta
        reasons << ["partner_absorbs", delta]
      elsif move_type == "GROUND" && Model.truthy(actor["partner_airborne"])
        reasons << ["partner_immune", 0]
      end
    end

    if !Model.truthy(action["spread"]) && !action["target"].nil?
      target = target_for(snapshot, action["target"])
      actor_ability_name = actor_ability(actor)
      steals = actor_ability_name != "STALWART" && actor_ability_name != "PROPELLERTAIL"
      if steals && target && REDIRECT_ABILITIES[(target["partner_ability"] || "").to_s.upcase] == move_type
        # The foe's partner takes the move instead, so it never reaches what it was
        # aimed at. Reborn already returns -1 for this (:3005) and the probe confirms;
        # the rule is here so the core does not depend on the adapter noticing.
        reasons << ["redirected_by_partner", HARD_REJECT]
        return HARD_REJECT
      end
      partner_ability = (actor["partner_ability"] || "").to_s.upcase
      if steals && REDIRECT_ABILITIES[partner_ability] == move_type
        # Reborn does NOT have this row: measured, it clicks Thunderbolt into a board
        # where its own Lightning Rod partner absorbs it (finding 2). Its own :3010
        # x0.3 is the symmetric case it does implement, so this is that number applied
        # to the direction the reference misses.
        delta = multiplier_delta(0.3, false, damage)
        score += delta
        reasons << ["own_partner_steals", delta]
      end
    end
    score
  end

  # Abilities on the TARGET that change what a damaging move is worth without changing
  # what it does.
  def self.damaging_ability_rules(action, target, lethal, score, reasons)
    return score if lethal
    ability = (target_fact(action, target, "ability") || "").to_s.upcase
    if ability == "JUSTIFIED" && (action["move_type"] || "").to_s.upcase == "DARK"
      # A Dark move that does not kill hands a Justified target a free Attack stage.
      score -= 40
      reasons << ["feeds_justified", -40]
    end
    score
  end

  def self.compare_candidates(a, b)
    by_score = b["score"] <=> a["score"]
    return by_score if by_score != 0
    action_key(a) <=> action_key(b)
  end

  def self.action_key(action)
    kind = action["type"] == "move" ? "0" : "1"
    [kind, action["slot"].to_i, action["target"].nil? ? -1 : action["target"].to_i,
     action["move_id"].to_s].join(":")
  end

  def self.pair_key(pair)
    pair.map { |action| action_key(action) }.join("|")
  end
end
# ===== END portable_ai/core.rb =====

# ===== BEGIN adapters/realidea/Portable_AI_Adapter.rb =====
# Portable AI adapter for Realidea (Pokemon Essentials v16).
#
# This file is concatenated after portable_ai/model.rb, effects.rb and core.rb, then
# injected as one script section after "AI edit clara" and before Main.
#
# Safe rollout: the hook is inert unless Data/portable_ai.txt exists or
# $PORTABLE_AI_ENABLED is explicitly true. Any unsupported state or registration failure
# falls back to the exact pbChooseMoves implementation that was live before this section.

module PortableAIRealidea
  # Essentials function code -> [effect kind, affected stat]. Mirrors the Reborn
  # adapter's MOVE_EFFECT_CODES, PRUNED to codes that exist in this build and EXTENDED
  # with Realidea's own. The base v16 space (0x05-0x21, 0x42-0x4F) is shared verbatim
  # and was checked move by move against PBS/moves.txt; everything Reborn carries above
  # 0x100 is a Reborn code that either does not exist here or means something else --
  # Reborn's 0x139 is a 3/4 drain, Realidea's is Play Nice; Reborn's 0x13f is a Speed
  # drop, Realidea's is Flower Shield. tools/check_move_codes.py is the guard.
  MOVE_EFFECT_CODES = {
    0x05 => ["poison", nil], 0x06 => ["poison", nil],
    0x07 => ["paralyze", nil], 0x08 => ["paralyze", nil], 0x09 => ["paralyze", nil],
    0x0A => ["burn", nil], 0x0B => ["burn", nil],
    0x0C => ["freeze", nil], 0x0D => ["freeze", nil], 0x0E => ["freeze", nil],
    0x0F => ["flinch", nil], 0x10 => ["flinch", nil], 0x11 => ["flinch", nil],
    # Target stat drops.
    0x42 => ["drop", "atk"],
    0x43 => ["drop", "def"], 0x4A => ["drop", "def"], 0x4C => ["drop", "def"],
    0x44 => ["drop", "speed"], 0x4D => ["drop", "speed"],
    0x45 => ["drop", "spa"],
    0x46 => ["drop", "spd"],
    0x47 => ["drop", "acc"],
    # Self-raise on a damaging move (Power-Up Punch, Flame Charge, Charge Beam).
    0x1C => ["self_raise", "atk"], 0x1D => ["self_raise", "def"],
    0x1E => ["self_raise", "def"], 0x1F => ["self_raise", "speed"],
    0x20 => ["self_raise", "spa"], 0x21 => ["self_raise", "spd"],
    # Realidea's own, read off 083_PokeBattle_MoveEffects.rb rather than guessed.
    0x139 => ["drop", "atk"],   # Play Nice      (:8847)
    0x13A => ["drop", "atk"],   # Noble Roar     (:8866, also SpAtk)
    0x13B => ["drop", "def"],   # Hyperspace Fury(:8912, secondary on the target)
    0x13C => ["drop", "spa"],   # Confide        (:8937)
    0x13D => ["drop", "spa"],   # Eerie Impulse  (:8956)
    0xCF14 => ["drop", "atk"]   # Tearful Look   (:9975, also SpAtk)
  }

  # Recoil as a fraction of the damage dealt. 0x10B (Jump Kick / High Jump Kick) is
  # crash damage on a MISS, not recoil, and is left out exactly as Reborn leaves it out.
  MOVE_RECOIL_CODES = {
    0xFA => 0.25, 0xFB => 0.3333, 0xFC => 0.5, 0xFD => 0.3333, 0xFE => 0.3333
  }

  # Fraction of the damage dealt that is restored to the user. 0x14F is Realidea's
  # 3/4 drain (Draining Kiss, Oblivion Wing) -- Reborn numbers the same effect 0x139.
  MOVE_DRAIN_CODES = { 0xDD => 0.5, 0xDE => 0.5, 0x14F => 0.75 }

  MULTI_HIT_CODES = [0xBD, 0xBE, 0xBF, 0xC0, 0xC1]

  # Pollen Puff HEALS the partner instead of damaging it (083:9897), so the friendly
  # fire charge must not apply when it is aimed there.
  PARTNER_HEAL_CODES = [0xCF19]

  # Abilities that make a move of the given type do nothing at all, read off this
  # engine's own pbTypeImmunityByAbility (082:318-402). The engine's copy CANNOT be
  # called from the AI: it raises the target's stats, heals it, sets Flash Fire and
  # prints -- it is the live effect, not a query. pbTypeModifier (:405) is ability-blind,
  # so without this table a Thunderbolt into Lightning Rod came back neutral and the
  # core scored it as a kill. (Reborn gets this free: pbTypeModNoMessages returns -1.)
  #
  # Bulletproof and Telepathy are in the engine's list too but key off the move's bomb
  # flag and ally targeting rather than its type, so they are handled at the call site.
  ABSORB_ABILITIES = {
    "SAPSIPPER" => :GRASS,
    "STORMDRAIN" => :WATER, "DRYSKIN" => :WATER, "WATERABSORB" => :WATER,
    "LIGHTNINGROD" => :ELECTRIC, "MOTORDRIVE" => :ELECTRIC, "VOLTABSORB" => :ELECTRIC,
    "FLASHFIRE" => :FIRE
  }

  ENABLE_FILE = "Data/portable_ai.txt"
  ERROR_FILE  = "Data/portable_ai_error.txt"
  ENABLE_WILD = false

  class BattleRNG
    def initialize(battle)
      @battle = battle
    end

    def rand(limit)
      @battle.pbAIRandom(limit)
    end
  end

  def self.requested?
    return true if defined?($PORTABLE_AI_ENABLED) && $PORTABLE_AI_ENABLED
    File.exist?(ENABLE_FILE)
  rescue
    false
  end

  def self.enabled_for?(battle, index)
    return false if !requested?
    return false if !battle.pbIsOpposing?(index)
    return false if !ENABLE_WILD && !battle.opponent
    true
  rescue
    false
  end

  def self.corrected_skill(owner)
    return 100 if !owner
    current = (owner.skill || 0).to_i rescue 0
    code = (owner.skillCode || "").to_s rescue ""
    # Realidea's intended 100 was written into the skillCode column. Only consume a
    # wholly numeric code, so actual script-like skill codes remain untouched.
    intended = (code =~ /\A\d+\z/) ? code.to_i : 0
    [current, intended].max
  end

  # Run-level config overrides, set from Data/ai_harness.txt by the gauntlet and the
  # probe. Keys not named there keep their skill-derived or Model::DEFAULT_CONFIG value.
  #
  # Same contract as the Reborn adapter (:150-186): one installed build plays both
  # sides of a policy A/B, and every gauntlet and probe record carries the overrides it
  # ran under. Without this Realidea could not ablate a single core rule without a
  # rebuild, which makes the two arms different artifacts.
  def self.config_overrides
    return {} if !defined?($PORTABLE_AI_CONFIG) || !$PORTABLE_AI_CONFIG.is_a?(Hash)
    $PORTABLE_AI_CONFIG
  end

  # Whether one core config key is on for this run, for the handful of rules that live
  # on THIS side of the boundary and so never see the config hash the core is handed.
  # Same precedence as Model.config: a run-level override wins, otherwise the default.
  def self.rule_enabled?(key)
    overrides = config_overrides
    return overrides[key] ? true : false if overrides.key?(key)
    PortableAI::Model::DEFAULT_CONFIG[key] ? true : false
  rescue
    true
  end

  def self.config_for(skill)
    base =
      if skill >= PBTrainerAI.bestSkill
        {
          "deterministic" => true, "noise" => 0, "switching" => true,
          "memory" => true, "coordination" => true, "knowledge" => "fair"
        }
      elsif skill >= PBTrainerAI.highSkill
        {
          "deterministic" => false, "noise" => 5, "switching" => true,
          "memory" => true, "coordination" => true, "knowledge" => "fair"
        }
      elsif skill >= PBTrainerAI.mediumSkill
        {
          "deterministic" => false, "noise" => 12, "switching" => true,
          "memory" => false, "coordination" => true, "knowledge" => "fair"
        }
      else
        {
          "deterministic" => false, "noise" => 25, "switching" => false,
          "memory" => false, "coordination" => false, "knowledge" => "fair"
        }
      end
    base.merge(config_overrides)
  end

  def self.choose(battle, index)
    plan = plan_for(battle)
    action = nil
    (plan["actions"] || []).each do |candidate|
      if candidate["actor_index"] == index
        action = candidate
        break
      end
    end
    return false if !action

    ok = apply_action(battle, index, action)
    if ok
      owner = battle.pbGetOwner(index) rescue nil
      if config_for(corrected_skill(owner))["memory"]
        apply_memory(battle, index, action)
      end
      trace = battle.instance_variable_get(:@portable_ai_decision_trace)
      if trace
        trace << {
          "turn" => battle.turncount,
          "actor" => index,
          "type" => action["type"],
          "slot" => action["slot"],
          "move_id" => action["move_id"],
          "target" => action["target"],
          "score" => action["score"],
          "view" => view_trace(
            battle.instance_variable_get(:@portable_ai_last_snapshot), index)
        }
      end
      return true
    end
    clear_cache(battle)
    false
  rescue Exception => error
    log_error(error, index)
    clear_cache(battle)
    false
  end

  def self.plan_for(battle)
    signature = cache_signature(battle)
    cached_signature = battle.instance_variable_get(:@portable_ai_cache_signature)
    cached = battle.instance_variable_get(:@portable_ai_plan)
    return cached if cached && cached_signature == signature

    snapshot, skill = build_snapshot(battle)
    plan = PortableAI.plan(snapshot, config_for(skill), BattleRNG.new(battle))
    battle.instance_variable_set(:@portable_ai_cache_signature, signature)
    battle.instance_variable_set(:@portable_ai_plan, plan)
    battle.instance_variable_set(:@portable_ai_last_plan, plan)
    battle.instance_variable_set(:@portable_ai_last_snapshot, snapshot)
    plan
  end

  # What the actor believed about the board when it chose: its own HP and speed order,
  # the incoming-damage estimates the heal and priority gates read, and the hits-to-KO
  # both ways per target. The race is reported AS COMPUTED, independently of whether
  # the run has the rules that consume it switched on -- a trace that only showed the
  # race when it was live could not say why a run with it off decided differently.
  DEFAULT_RACE_CONFIG = { "damage_race" => true }

  def self.view_trace(snapshot, index)
    return {} if !snapshot
    actor = nil
    (snapshot["actors"] || []).each do |candidate|
      actor = candidate if candidate["index"] == index
    end
    return {} if !actor
    race = {}
    (snapshot["targets"] || []).each do |target|
      race[target["index"].to_s] =
        PortableAI.damage_race(snapshot, actor, target, DEFAULT_RACE_CONFIG)
    end
    {
      "hp_pct" => actor["hp_pct"],
      "speed" => actor["speed"],
      "faster" => actor["faster"],
      "incoming_damage_pct" => actor["incoming_damage_pct"],
      "certain_incoming_damage_pct" => actor["certain_incoming_damage_pct"],
      "threatened_lethal" => actor["threatened_lethal"],
      "race" => race
    }
  rescue
    {}
  end

  def self.clear_cache(battle)
    return if !battle
    battle.instance_variable_set(:@portable_ai_cache_signature, nil)
    battle.instance_variable_set(:@portable_ai_plan, nil)
    battle.instance_variable_set(:@portable_ai_last_plan, nil)
    battle.instance_variable_set(:@portable_ai_last_snapshot, nil)
  rescue
  end

  def self.cache_signature(battle)
    active = []
    [1, 3].each do |i|
      battler = battle.battlers[i] rescue nil
      next if !battler || battler.isFainted?
      active << [i, battler.pokemonIndex, battler.hp, battler.status]
    end
    [battle.turncount, active]
  end

  def self.build_snapshot(battle)
    indices = [1]
    indices << 3 if battle.doublebattle
    indices = indices.select do |i|
      battler = battle.battlers[i] rescue nil
      battler && !battler.isFainted?
    end
    raise "no active opposing battlers" if indices.empty?

    foe_indices = [0]
    foe_indices << 2 if battle.doublebattle
    foe_indices = foe_indices.select do |i|
      battler = battle.battlers[i] rescue nil
      battler && !battler.isFainted?
    end

    skills = indices.map { |i| corrected_skill(battle.pbGetOwner(i)) }
    skill = skills.min || 100
    targets = foe_indices.map { |i| battler_view(battle.battlers[i], battle, skill) }
    actors = indices.map do |i|
      build_actor(battle, i, foe_indices, skill)
    end

    memory = battle.instance_variable_get(:@portable_ai_memory) || {}
    [{
      "format" => battle.doublebattle ? "double" : "single",
      "turn" => battle.turncount,
      "weather" => weather_name(battle),
      "trick_room_active" => trick_room_active?(battle),
      "tailwind_active" => (safe_side_effect(battle.sides[1], :Tailwind, 0).to_i > 0),
      "actors" => actors,
      "targets" => targets,
      "memory" => memory
    }, skill]
  end

  def self.battler_view(battler, battle, skill)
    physical, special = attack_bias(battle, battler, skill)
    partner = (battler.pbPartner rescue nil)
    {
      "index" => battler.index,
      "species" => battler.species,
      "hp_pct" => percent(battler.hp, battler.totalhp),
      "status" => battler.status,
      "types" => [battler.type1, battler.type2],
      "speed" => battler_speed(battler),
      # Switch scoring needs the foe's boost level and, unlike a move action, has no
      # scoring target to read it from (core.rb foe_boost_total).
      "positive_stages" => positive_stages(battler),
      # 0.5.0 facts. Plain uppercase names and booleans only: the core matches them
      # against its own tables and never sees a PBAbilities/PBItems constant.
      "ability" => ability_key(battler),
      "item" => item_key(battler),
      "full_hp" => (battler.hp >= battler.totalhp),
      "physical_attacker" => physical,
      "special_attacker" => special,
      "substitute" => (safe_effect(battler, :Substitute, 0).to_i > 0),
      "partner_ability" => (partner && !partner.isFainted? ? ability_key(partner) : nil)
    }
  end

  def self.build_actor(battle, index, foe_indices, skill)
    battler = battle.battlers[index]
    actions = []
    battler.moves.each_with_index do |move, slot|
      next if !move || move.id == 0
      next if !battle.pbCanChooseMove?(index, slot, false)
      move_actions(battle, battler, move, slot, foe_indices, skill).each do |action|
        actions << action
      end
    end
    switch_actions(battle, battler, foe_indices, skill).each { |action| actions << action }

    damaging = actions.select { |action| action["type"] == "move" && action["damaging"] }
    best_damage = 0
    damaging.each do |action|
      damage = PortableAI::Model.number(action["expected_damage_pct"], 0)
      best_damage = damage if damage > best_damage
    end
    no_effective = !damaging.empty? && damaging.all? do |action|
      PortableAI::Model.truthy(action["immune"]) ||
        PortableAI::Model.number(action["effectiveness"], 1) <= 0
    end
    negative_stages = 0
    battler.stages.each { |stage| negative_stages += stage if stage && stage < 0 }
    speed = battler_speed(battler)
    partner = (battler.pbPartner rescue nil)
    partner_alive = (partner && !partner.isFainted?) ? true : false

    incoming_map = incoming_damage_by_move(battle, battler, foe_indices, skill)
    incoming = 0.0
    incoming_map.each_value { |damage| incoming = damage if damage > incoming }
    certain = certain_incoming_damage(battle, battler, foe_indices, incoming_map, skill)
    toxic_stage = safe_effect(battler, :Toxic, 0).to_i
    residual = 0.0
    residual += (toxic_stage + 1) * 100.0 / 16.0 if toxic_stage > 0
    residual += 100.0 / 8.0 if safe_effect(battler, :LeechSeed, -1).to_i >= 0
    {
      "index" => index,
      "species" => battler.species,
      "hp_pct" => percent(battler.hp, battler.totalhp),
      "status" => battler.status,
      "speed" => speed,
      "faster" => faster_than_foes?(battle, speed, foe_indices),
      "stages" => battler.stages.clone,
      "negative_stage_total" => negative_stages,
      # 0.6.2: the durable record of "I have already set up", which the memory counter
      # is not -- apply_memory zeroes it on any non-setup action.
      "positive_stage_total" => positive_stages(battler),
      "incoming_damage_pct" => incoming,
      "certain_incoming_damage_pct" => certain,
      "incoming_by_move" => incoming_map,
      # 0.6.0: the per-foe view of the same threat, which is what a hits-to-KO question
      # has to read. Absent on an adapter that does not build it, and the core's
      # damage_race then returns nil and every consumer goes inert.
      "threats_by_foe" => threats_by_foe(battle, battler, foe_indices, incoming_map, skill),
      "threatened_lethal" => incoming >= percent(battler.hp, battler.totalhp),
      "no_effective_move" => no_effective,
      "best_damage_pct" => best_damage,
      "yawned" => safe_effect(battler, :Yawn, 0).to_i > 0,
      "residual_damage_pct" => residual,
      "trapped" => !has_legal_switch?(battle, index),
      "ability" => ability_key(battler),
      "item" => item_key(battler),
      # Mold Breaker turns the target's Sturdy off, so the kill call stands.
      "mold_breaker" => (battler.hasMoldBreaker rescue false) ? true : false,
      "slower_bench_count" => slower_bench_count(battle, battler, foe_indices),
      "partner_alive" => partner_alive,
      "partner_ability" => (partner_alive ? ability_key(partner) : nil),
      "partner_hp_pct" => (partner_alive ? percent(partner.hp, partner.totalhp) : nil),
      "partner_airborne" => (partner_alive ? (partner.isAirborne? rescue false) : false),
      # Fake Out and First Impression are worth +115 on turn 0 and nothing after.
      # Without this the core's turn_shape_rules fired every turn and the AI re-clicked
      # a move the engine refuses (core.rb first_turn_hit).
      "turncount" => (battler.turncount.to_i rescue 0),
      "actions" => actions
    }
  end

  def self.move_actions(battle, battler, move, slot, foe_indices, skill)
    targets = legal_targets(battle, battler, move, foe_indices)
    spread = PBTargets.hasMultipleTargets?(move)
    move_id = move_key(move.id)

    if spread
      scored = foe_indices.map do |target_index|
        target = battle.battlers[target_index]
        action_for_target(battle, battler, move, slot, move_id, target, nil, skill)
      end
      return [] if scored.empty?
      action = scored[0]
      action["base_score"] = average(scored.map { |item| item["base_score"] })
      action["expected_damage_pct"] = scored.inject(0) do |sum, item|
        sum + PortableAI::Model.number(item["expected_damage_pct"], 0)
      end
      action["target"] = nil
      action["spread"] = true
      if PortableAI::Effects.tagged?(move_id, [], "friendly_fire")
        partner = battler.pbPartner
        if partner && !partner.isFainted?
          action["friendly_fire_pct"] = rough_damage_pct(battle, move, battler, partner, skill)
          action["partner_hp_pct"] = percent(partner.hp, partner.totalhp)
        end
      end
      return [action]
    end

    if targets.empty?
      opponent = foe_indices.empty? ? nil : battle.battlers[foe_indices[0]]
      return [action_for_target(battle, battler, move, slot, move_id, opponent, nil, skill)]
    end

    targets.map do |target_index|
      target = battle.battlers[target_index]
      registration_target = explicit_target?(move) ? target_index : nil
      action = action_for_target(
        battle, battler, move, slot, move_id, target, registration_target, skill
      )
      partner = battler.pbPartner
      if partner && target_index == partner.index
        action["friendly_target"] = true
        # Pollen Puff aimed at the partner is a HEAL, not friendly fire (083:9897).
        heals = PARTNER_HEAL_CODES.include?((move.function rescue nil))
        if move.pbIsDamaging? && !heals
          action["friendly_fire_pct"] = action["expected_damage_pct"]
          action["partner_hp_pct"] = percent(partner.hp, partner.totalhp)
        end
      end
      action
    end
  end

  def self.action_for_target(battle, battler, move, slot, move_id, target, register_target, skill)
    scoring_target = target
    scoring_target = battler.pbOppositeOpposing if !scoring_target || scoring_target.index == battler.index
    base = battle.pbGetMoveScore(move, battler, scoring_target, skill)
    effectiveness = type_effectiveness(battle, move, battler, scoring_target)
    tags = PortableAI::Effects.describe(move_id, [])
    blocked = !move.pbIsDamaging? && status_blocked?(move, tags, battler, scoring_target)
    kind, stat, chance = move_effect(battle, move, battler, scoring_target)
    physical, special = scoring_target ? attack_bias(battle, scoring_target, skill) : [false, false]
    code = (move.function rescue nil)
    {
      "type" => "move",
      "actor_index" => battler.index,
      "slot" => slot,
      "move_id" => move_id,
      "numeric_move_id" => move.id,
      "target" => register_target,
      "base_score" => base,
      "damaging" => move.pbIsDamaging?,
      "power" => move.basedamage,
      "priority" => effective_priority(move, battler),
      # 0.5.0 move facts, all from the engine.
      "move_type" => type_key((move.pbType(move.type, battler, scoring_target) rescue move.type)),
      "contact" => ((move.isContactMove? rescue false) ? true : false),
      "effect_kind" => kind,
      "effect_stat" => stat,
      "effect_chance" => chance,
      "multi_hit" => multi_hit?(move),
      "recoil_fraction" => MOVE_RECOIL_CODES[code],
      "drain_fraction" => MOVE_DRAIN_CODES[code],
      "mold_breaker" => (battler.hasMoldBreaker rescue false) ? true : false,
      # Mirrors of the target view, so a spread action (which has no single target) and
      # a unit test both reach the same facts.
      "target_species" => (scoring_target ? scoring_target.species : nil),
      "target_ability" => (scoring_target ? ability_key(scoring_target) : nil),
      "target_item" => (scoring_target ? item_key(scoring_target) : nil),
      "target_full_hp" =>
        (scoring_target ? (scoring_target.hp >= scoring_target.totalhp) : false),
      "target_speed" => (scoring_target ? battler_speed(scoring_target) : nil),
      "target_physical_attacker" => physical,
      "target_special_attacker" => special,
      "target_substitute" =>
        (scoring_target ? (safe_effect(scoring_target, :Substitute, 0).to_i > 0) : false),
      "effectiveness" => effectiveness,
      "immune" => (move.pbIsDamaging? && effectiveness <= 0) || blocked,
      "expected_damage_pct" => rough_damage_pct(battle, move, battler, scoring_target, skill),
      "accuracy" => rough_accuracy(battle, move, battler, scoring_target, skill),
      "target_hp_pct" => (scoring_target ? percent(scoring_target.hp, scoring_target.totalhp) : nil),
      "tags" => tags,
      "spread" => false,
      "existing_layers" => existing_layers(battle, move_id, false),
      "max_layers" => max_layers(move_id),
      "own_hazard_layers" => own_hazard_layers(battle),
      "foe_hazard_layers" => opposing_hazard_layers(battle),
      "target_positive_stages" => positive_stages(scoring_target),
      "effect_active" => effect_active?(battle, move_id, battler),
      # NOTE: no "failed_last_turn". The Reborn adapter reads PBEffects::Tantrum, the
      # flag its engine keeps for Stomping Tantrum. Realidea declares the equivalent as
      # PBEffects::LastMoveFailed = 4 -- but in the MOVE-USAGE namespace, which is the
      # same index as the BATTLER effect BideDamage = 4 (075_PBEffects.rb:8 and :170).
      # The battler's copy is initialised to false (080:415) and NOTHING in the build
      # ever sets it true; the only writes to index 4 are Bide's damage accumulator, so
      # this engine's own Stomping Tantrum doubling is dead code. successStates is not
      # a substitute: useState is set to 2 only on the damaging path (080:3223), so a
      # status move that worked perfectly reads back as 1 = failed.
      #
      # Exporting the key from either source would be worse than leaving it out: the
      # core's move_memory rule takes 200 points off a move, and it would take them off
      # the wrong ones. Absent, Model.truthy reads nil and the rule is inert, which is
      # the honest answer for this engine. AI_Probe::UNSUPPORTED skips the corpus pair
      # that tests it.
      "foe_reserves" => reserve_count(battle, battler.pbOppositeOpposing.index),
      "hazard_targets" => hazard_target_count(battle, move_id, battler.index),
      "own_reserves" => reserve_count(battle, battler.index)
    }
  end

  def self.legal_targets(battle, battler, move, foe_indices)
    case move.target
    when PBTargets::SingleNonUser
      out = foe_indices.clone
      partner = battler.pbPartner
      out << partner.index if partner && !partner.isFainted?
      out
    when PBTargets::SingleOpposing
      foe_indices.clone
    when PBTargets::OppositeOpposing
      target = battler.pbOppositeOpposing
      target = target.pbPartner if target && target.isFainted?
      target && !target.isFainted? ? [target.index] : []
    when PBTargets::RandomOpposing
      foe_indices.clone
    when PBTargets::User
      [battler.index]
    when PBTargets::UserOrPartner
      out = [battler.index]
      partner = battler.pbPartner
      out << partner.index if partner && !partner.isFainted?
      out
    when PBTargets::Partner
      partner = battler.pbPartner
      partner && !partner.isFainted? ? [partner.index] : []
    else
      []
    end
  end

  def self.explicit_target?(move)
    move.target == PBTargets::SingleNonUser ||
      move.target == PBTargets::SingleOpposing ||
      move.target == PBTargets::UserOrPartner ||
      move.target == PBTargets::Partner
  end

  def self.switch_actions(battle, battler, foe_indices, skill)
    party = battle.pbParty(battler.index)
    forced = safe_effect(battler, :PerishSong, 0) == 1
    actions = []
    party.each_with_index do |pokemon, slot|
      next if !pokemon || !battle.pbCanSwitch?(battler.index, slot, false)
      hp_pct = percent(pokemon.hp, pokemon.totalhp)
      matchup = switch_matchup(pokemon, battle, foe_indices)
      hazard = entry_hazard_pct(battle, pokemon, battler)
      next if hazard >= hp_pct
      action = {
        "type" => "switch",
        "actor_index" => battler.index,
        "slot" => slot,
        "base_score" => 20 + hp_pct * 0.35 - hazard,
        "matchup_score" => matchup,
        "incoming_risk" => switch_incoming_risk(pokemon, battle, foe_indices),
        "forced" => forced,
        "safe_entry" => hp_pct > hazard + 20,
        "species" => pokemon.species,
        # candidate_hp_pct and entry_damage_pct restate what is already folded into
        # base_score so the core can ask "is this Pokemon alive at the end of the turn
        # it comes in on" rather than "did it clear the hazards".
        "candidate_hp_pct" => hp_pct,
        "entry_damage_pct" => hazard
      }
      real = switch_incoming_damage(battle, pokemon, slot, battler, foe_indices, skill)
      action["incoming_damage_pct"] = real if !real.nil?
      out = switch_outgoing_damage(battle, pokemon, slot, battler, foe_indices, skill)
      action["outgoing_damage_pct"] = out if !out.nil?
      fast = switch_candidate_faster(battle, pokemon, foe_indices)
      action["faster"] = fast if !fast.nil?
      actions << action
    end
    actions
  end

  # A battler object for a Pokemon that is not on the field, so the entry estimates can
  # be real damage rolls rather than a type-chart proxy. This is what Reborn's
  # pbMakeFakeBattler does internally; v16 has no such helper, so it is spelled out.
  #
  # PokeBattle_Battler#initialize is NOT pure. pbInitEffects reaches across to every
  # OTHER battler and clears whatever points at the index being built -- Lock-On
  # (080:338-345), infatuation (:374-378) and Mean Look (:418-424). Building a fake at
  # the actor's own index would therefore silently cancel a real Lock-On, Attract or
  # trap on the board it is only supposed to be measuring, so all four effect slots are
  # snapshotted and restored. pbInitPokemon itself only copies stats and builds move
  # objects through pbFromPBMove (:203-241); those are the only three writes in the
  # whole constructor that leave the new battler.
  #
  # nil when the engine refuses, which leaves the core on the type proxy it used
  # through 0.1.0.
  RESTORED_ON_FAKE = [:Attract, :MeanLook, :LockOn, :LockOnPos]

  def self.fake_battler(battle, pokemon, party_index, index)
    saved = []
    for i in 0...4
      other = battle.battlers[i]
      next if !other
      values = []
      RESTORED_ON_FAKE.each { |name| values << safe_effect(other, name, nil) }
      saved << [other, values]
    end
    begin
      fake = PokeBattle_Battler.new(battle, index)
      fake.pbInitPokemon(pokemon, party_index)
      fake
    ensure
      saved.each do |entry|
        RESTORED_ON_FAKE.each_with_index do |name, slot|
          value = entry[1][slot]
          next if value.nil?
          next if !PBEffects.const_defined?(name.to_s)
          entry[0].effects[PBEffects.const_get(name.to_s)] = value
        end
      end
    end
  rescue
    nil
  end

  # What the candidate actually eats on the turn it comes in, with its own Intimidate
  # applied to the foes first -- the only way an entry ability shows up in the number
  # at all. The temporary stage mutation is restored in `ensure`; pbCanReduceStatStage?
  # is what makes Clear Body, White Smoke, Full Metal Body and Hyper Cutter exempt.
  def self.switch_incoming_damage(battle, pokemon, party_index, battler, foe_indices, skill)
    fake = fake_battler(battle, pokemon, party_index, battler.index)
    return nil if !fake
    intimidate = (ability_key(pokemon) == "INTIMIDATE")
    saved = {}
    worst = 0.0
    begin
      if intimidate
        foe_indices.each do |foe_index|
          foe = battle.battlers[foe_index]
          next if !foe || foe.isFainted?
          next if !(foe.pbCanReduceStatStage?(PBStats::ATTACK) rescue false)
          next if (foe.item == PBItems::WHITEHERB rescue false)
          ability = ability_key(foe)
          next if ability == "CONTRARY" || ability == "DEFIANT" || ability == "COMPETITIVE"
          saved[foe_index] = foe.stages[PBStats::ATTACK]
          foe.stages[PBStats::ATTACK] -= 1
        end
      end
      foe_indices.each do |foe_index|
        foe = battle.battlers[foe_index]
        next if !foe || foe.isFainted?
        foe.moves.each do |known|
          next if !known || known.id == 0
          damage = rough_damage_pct(battle, known, foe, fake, skill)
          worst = damage if damage > worst
        end
      end
    ensure
      saved.each do |foe_index, value|
        battle.battlers[foe_index].stages[PBStats::ATTACK] = value
      end
    end
    worst
  rescue
    nil
  end

  # The mirror: the best real hit this candidate has into any current foe, so the core
  # can ask how many turns it needs rather than only how many it survives. v16's
  # pbFromPBMove takes (battle, move) -- no user argument (082:50).
  def self.switch_outgoing_damage(battle, pokemon, party_index, battler, foe_indices, skill)
    fake = fake_battler(battle, pokemon, party_index, battler.index)
    return nil if !fake
    best = 0.0
    foe_indices.each do |foe_index|
      foe = battle.battlers[foe_index]
      next if !foe || foe.isFainted?
      (pokemon.moves || []).each do |own|
        next if !own || own.id == 0
        move = (PokeBattle_Move.pbFromPBMove(battle, own) rescue nil)
        next if !move
        damage = rough_damage_pct(battle, move, fake, foe, skill)
        best = damage if damage > best
      end
    end
    best
  rescue
    nil
  end

  # Whether the candidate would outrun every current foe once it is in. A benched
  # Pokemon has no battler and therefore no pbSpeed, so this reads the party entry's own
  # Speed stat -- no stages, which is right: a switch-in enters at stage 0.
  def self.switch_candidate_faster(battle, pokemon, foe_indices)
    speed = (pokemon.speed rescue nil)
    return nil if speed.nil?
    faster_than_foes?(battle, speed, foe_indices)
  rescue
    nil
  end

  # The mirror of switch_matchup: how hard the foe hits the candidate coming in, scored
  # off the foe's own types rather than its moveset so this stays inside the
  # fair-information contract. Same units as switch_matchup (neutral 8, x4 = 32), and
  # the worst foe is taken rather than the sum.
  def self.switch_incoming_risk(pokemon, battle, foe_indices)
    worst = 0
    types = [pokemon.type1, pokemon.type2].compact.uniq
    foe_indices.each do |foe_index|
      foe = battle.battlers[foe_index]
      next if !foe
      [foe.type1, foe.type2].compact.uniq.each do |attacking|
        value = PBTypes.getCombinedEffectiveness(attacking, types[0], types[-1], -1)
        worst = value if value > worst
      end
    end
    worst * 4
  rescue
    0
  end

  # How many benched Pokemon are slower than every current foe. Trick Room is a
  # whole-team investment, so it is only worth a turn when the team behind the actor is
  # slow too.
  def self.slower_bench_count(battle, battler, foe_indices)
    fastest = 0
    foe_indices.each do |foe_index|
      speed = battler_speed(battle.battlers[foe_index])
      fastest = speed if speed && speed > fastest
    end
    return 0 if fastest <= 0
    count = 0
    battle.pbParty(battler.index).each_with_index do |pokemon, slot|
      next if !pokemon || pokemon.hp <= 0 || pokemon.isEgg?
      next if slot == battler.pokemonIndex
      speed = (pokemon.speed rescue nil)
      count += 1 if speed && speed < fastest
    end
    count
  rescue
    0
  end

  def self.switch_matchup(pokemon, battle, foe_indices)
    best = 0
    (pokemon.moves || []).each do |pokemon_move|
      next if !pokemon_move || pokemon_move.id == 0
      data = PBMoveData.new(pokemon_move.id) rescue nil
      next if !data || data.basedamage <= 0
      total = 0
      foe_indices.each do |foe_index|
        foe = battle.battlers[foe_index]
        type3 = safe_effect(foe, :Type3, -1)
        total += PBTypes.getCombinedEffectiveness(data.type, foe.type1, foe.type2, type3)
      end
      best = total if total > best
    end
    best * 4
  rescue
    0
  end

  def self.type_effectiveness(battle, move, attacker, target)
    return 1.0 if !target || !move.pbIsDamaging?
    return 0.0 if absorbed_by_ability?(move, attacker, target)
    move.pbTypeModifier(move.type, attacker, target).to_f / 8.0
  rescue
    1.0
  end

  # The read-only half of pbTypeImmunityByAbility (082:318-402). Same two guards the
  # engine opens with: a move aimed at the user itself is exempt, and Mold Breaker
  # switches the whole check off.
  def self.absorbed_by_ability?(move, attacker, target)
    return false if attacker.index == target.index
    return false if (attacker.hasMoldBreaker rescue false)
    # Telepathy: an ally's damaging move never lands on the holder.
    if ability_key(target) == "TELEPATHY" && !target.pbIsOpposing?(attacker.index)
      return true
    end
    return true if ability_key(target) == "BULLETPROOF" && (move.isBombMove? rescue false)
    wanted = ABSORB_ABILITIES[ability_key(target)]
    return false if !wanted
    type = (move.pbType(move.type, attacker, target) rescue move.type)
    value = (PBTypes.const_get(wanted) rescue nil)
    !value.nil? && type == value
  rescue
    false
  end

  # Same base-damage preparation stock v16 does before it calls pbRoughDamage
  # (085_PokeBattle_AI.rb:2802-2810): basedamage 1 is the "variable power" sentinel and
  # scores as 60, and pbBetterBaseDamage resolves the ~30 function codes that compute
  # their own power (Seismic Toss, Super Fang, Night Shade, Gyro Ball, Grass Knot...).
  # Passing raw basedamage instead, as this adapter did through 0.1.0, priced every one
  # of those at its sentinel.
  def self.rough_damage_pct(battle, move, attacker, target, skill)
    return 0.0 if !target || !move.pbIsDamaging? || move.basedamage <= 0
    base = move.basedamage
    base = 60 if base == 1
    base = battle.pbBetterBaseDamage(move, attacker, target, skill, base) rescue base
    damage = battle.pbRoughDamage(move, attacker, target, skill, base)
    percent(damage, target.totalhp)
  rescue
    0.0
  end

  def self.battler_speed(battler)
    return nil if !battler
    (battler.pbSpeed rescue battler.speed)
  rescue
    nil
  end

  # Hit chance 0-100 as the engine computes it, including ability, weather and
  # accuracy/evasion stages (085:3716). 125 is v16's never-miss sentinel (:3770), so it
  # is clamped rather than handed to the core as a >100 probability. nil when the
  # primitive is unavailable, which the core reads as "do not discount".
  def self.rough_accuracy(battle, move, attacker, target, skill)
    return nil if !target
    value = battle.pbRoughAccuracy(move, attacker, target, skill)
    return nil if value.nil?
    value = 100 if value > 100
    value.to_f
  rescue
    nil
  end

  # Priority as the engine brackets it (084:1105-1113): Prankster on a status move,
  # Gale Wings on a Flying move, Triage on a healing move. Nothing else moves priority
  # in this build -- Psychic Terrain is set by move 0x169 and read by NOTHING, so the
  # Reborn clause that zeroes a priority move under it is deliberately absent here.
  def self.effective_priority(move, battler)
    priority = move.priority
    if (battler.hasWorkingAbility(:PRANKSTER) rescue false) && (move.pbIsStatus? rescue false)
      priority += 1
    end
    flying = (PBTypes.const_get(:FLYING) rescue nil)
    if (battler.hasWorkingAbility(:GALEWINGS) rescue false) && !flying.nil? &&
       move.type == flying
      priority += 1
    end
    if (battler.hasWorkingAbility(:TRIAGE) rescue false) && (move.isHealingMove? rescue false)
      priority += 3
    end
    priority
  rescue
    move.priority
  end

  # Reborn's own convention (pbAIfaster?): strictly greater is faster, a tie is not,
  # and Trick Room inverts the comparison. nil when either speed is unavailable, which
  # every rule reading it treats as "unknown, do not penalise".
  def self.faster_than_foes?(battle, speed, foe_indices)
    return nil if speed.nil?
    fastest = nil
    foe_indices.each do |foe_index|
      foe_speed = battler_speed(battle.battlers[foe_index])
      next if foe_speed.nil?
      fastest = foe_speed if fastest.nil? || foe_speed > fastest
    end
    return nil if fastest.nil?
    trick_room_active?(battle) ? speed < fastest : speed > fastest
  end

  def self.trick_room_active?(battle)
    safe_field_effect(battle, :TrickRoom, 0).to_i > 0
  rescue
    false
  end

  # Every foe move's estimated hit on this battler, keyed "<foe index>:<move id>". The
  # maximum is what the threat rules read.
  #
  # A Choice item that has already locked in is a CERTAINTY about what is coming and the
  # strongest one available: the foe cannot use anything else until it switches
  # (PBEffects::ChoiceBand holds the move id, -1 when free, 080:3725).
  def self.incoming_damage_by_move(battle, battler, foe_indices, skill)
    out = {}
    foe_indices.each do |foe_index|
      foe = battle.battlers[foe_index]
      next if !foe
      locked = safe_effect(foe, :ChoiceBand, -1).to_i
      foe.moves.each do |known|
        next if !known || known.id == 0
        next if locked >= 0 && known.id != locked
        out["#{foe_index}:#{known.id}"] = rough_damage_pct(battle, known, foe, battler, skill)
      end
    end
    out
  end

  # The same incoming_map resolved PER FOE, with the two extra facts a hits-to-KO
  # question needs: that foe's best hit, its best hit that moves first, and whether it
  # outruns this battler. incoming_by_move is keyed "foe:moveid" with no priority, and
  # actor["faster"] is against the FASTEST foe only -- in doubles that is the wrong
  # flag for the slower target and a race computed off it is wrong.
  #
  # Keyed by foe index as a STRING, because the core reads it out of a plain Hash that
  # has been through JSON in the probe's results file.
  def self.threats_by_foe(battle, battler, foe_indices, incoming_map, skill)
    speed = battler_speed(battler)
    out = {}
    foe_indices.each do |foe_index|
      foe = battle.battlers[foe_index]
      next if !foe || foe.isFainted?
      locked = safe_effect(foe, :ChoiceBand, -1).to_i
      best = 0.0
      best_priority = 0.0
      foe.moves.each do |known|
        next if !known || known.id == 0
        next if locked >= 0 && known.id != locked
        # Reuse the map the actor already paid for; fall back for anything not in it.
        damage = incoming_map["#{foe_index}:#{known.id}"]
        damage = rough_damage_pct(battle, known, foe, battler, skill) if damage.nil?
        damage = PortableAI::Model.number(damage, 0.0)
        best = damage if damage > best
        next if effective_priority(known, foe) <= 0
        best_priority = damage if damage > best_priority
      end
      out[foe_index.to_s] = {
        "damage_pct" => best,
        "priority_damage_pct" => best_priority,
        "faster" => faster_than_foes?(battle, speed, [foe_index])
      }
    end
    out
  rescue
    {}
  end

  def self.estimated_incoming_damage(battle, battler, foe_indices, skill)
    maximum = 0.0
    incoming_damage_by_move(battle, battler, foe_indices, skill).each_value do |damage|
      maximum = damage if damage > maximum
    end
    maximum
  end

  # The largest incoming hit that cannot fail to happen: the foe is not frozen or asleep
  # with sleep still to serve, and the move never misses as the engine computes its hit
  # chance. The core's "you die whatever you click" rules read this under strict_threat;
  # the loose maximum stays for the soft rules.
  def self.certain_incoming_damage(battle, battler, foe_indices, incoming_map, skill)
    maximum = 0.0
    foe_indices.each do |foe_index|
      foe = battle.battlers[foe_index]
      next if !foe || !foe_can_act?(foe)
      foe.moves.each do |known|
        next if !known || known.id == 0
        damage = incoming_map["#{foe_index}:#{known.id}"]
        next if !damage || damage <= 0
        accuracy = rough_accuracy(battle, known, foe, battler, skill)
        next if !accuracy.nil? && accuracy < 100
        maximum = damage if damage > maximum
      end
    end
    maximum
  end

  def self.foe_can_act?(foe)
    status = foe.status
    return false if status == PBStatuses::FROZEN
    if status == PBStatuses::SLEEP
      # One turn left means it wakes and acts this turn.
      return false if (foe.statusCount rescue 0).to_i > 1
    end
    true
  rescue
    true
  end

  def self.has_legal_switch?(battle, index)
    party = battle.pbParty(index)
    party.each_with_index do |pokemon, slot|
      return true if pokemon && battle.pbCanSwitch?(index, slot, false)
    end
    false
  rescue
    false
  end

  def self.reserve_count(battle, index)
    count = 0
    party = battle.pbParty(index)
    party.each_with_index do |pokemon, slot|
      next if !pokemon || pokemon.hp <= 0 || pokemon.isEgg?
      active = battle.battlers.any? do |battler|
        battler && battle.pbIsOpposing?(battler.index) == battle.pbIsOpposing?(index) &&
          battler.pokemonIndex == slot && !battler.isFainted?
      end
      count += 1 if !active
    end
    count
  rescue
    0
  end

  def self.hazard_target_count(battle, move_id, actor_index)
    party = battle.pbOpposingParty(actor_index)
    count = 0
    party.each do |pokemon|
      next if !pokemon || pokemon.hp <= 0 || pokemon.isEgg?
      # The other half of the exemption above: a party that walks over hazards is a
      # party the hazard move cannot touch.
      next if pokemon_item_key(pokemon) == "HEAVYDUTYBOOTS"
      next if pokemon.hasAbility?(:MAGICGUARD)
      airborne = pokemon.hasType?(:FLYING) || pokemon.hasAbility?(:LEVITATE)
      if move_id == "SPIKES" || move_id == "STICKYWEB"
        count += 1 if !airborne
      elsif move_id == "TOXICSPIKES"
        immune_type = pokemon.hasType?(:POISON) || pokemon.hasType?(:STEEL)
        count += 1 if !airborne && !immune_type
      else
        count += 1
      end
    end
    count
  rescue
    1
  end

  def self.existing_layers(battle, move_id, own_side)
    side = own_side ? battle.sides[1] : battle.sides[0]
    case move_id
    when "SPIKES"       then safe_side_effect(side, :Spikes, 0)
    when "TOXICSPIKES"  then safe_side_effect(side, :ToxicSpikes, 0)
    when "STEALTHROCK"  then safe_side_effect(side, :StealthRock, false) ? 1 : 0
    when "STICKYWEB"     then safe_side_effect(side, :StickyWeb, false) ? 1 : 0
    else 0
    end
  end

  def self.max_layers(move_id)
    return 3 if move_id == "SPIKES"
    return 2 if move_id == "TOXICSPIKES"
    1
  end

  # Hazards already sitting on the half of the field this battler would lay them on.
  def self.opposing_hazard_layers(battle)
    side = battle.sides[0]
    safe_side_effect(side, :Spikes, 0).to_i +
      safe_side_effect(side, :ToxicSpikes, 0).to_i +
      (safe_side_effect(side, :StealthRock, false) ? 1 : 0) +
      (safe_side_effect(side, :StickyWeb, false) ? 1 : 0)
  rescue
    0
  end

  def self.own_hazard_layers(battle)
    side = battle.sides[1]
    safe_side_effect(side, :Spikes, 0).to_i +
      safe_side_effect(side, :ToxicSpikes, 0).to_i +
      (safe_side_effect(side, :StealthRock, false) ? 1 : 0) +
      (safe_side_effect(side, :StickyWeb, false) ? 1 : 0)
  rescue
    0
  end

  def self.effect_active?(battle, move_id, battler)
    side = battle.sides[1]
    case move_id
    when "REFLECT"     then safe_side_effect(side, :Reflect, 0).to_i > 0
    when "LIGHTSCREEN" then safe_side_effect(side, :LightScreen, 0).to_i > 0
    when "SAFEGUARD"   then safe_side_effect(side, :Safeguard, 0).to_i > 0
    when "SUBSTITUTE"  then safe_effect(battler, :Substitute, 0).to_i > 0
    # 0.6.2. Wish fails outright with a Wish already pending. PBEffects::Wish is the
    # countdown on the USER, not a side effect, which is why it is read off the battler.
    when "WISH"        then safe_effect(battler, :Wish, 0).to_i > 0
    else false
    end
  end

  def self.entry_hazard_pct(battle, pokemon, battler)
    side = battle.sides[1]
    # Heavy-Duty Boots and Magic Guard walk over every hazard, so a holder pays nothing
    # to come in. (Boots does not exist in this build's item list; the row costs
    # nothing and keeps the two adapters saying the same thing.)
    return 0 if pokemon_item_key(pokemon) == "HEAVYDUTYBOOTS"
    return 0 if pokemon.hasAbility?(:MAGICGUARD)
    spikes = safe_side_effect(side, :Spikes, 0).to_i
    damage = [0, 12.5, 16.7, 25.0][spikes] || 25.0
    if pokemon.hasType?(:FLYING) || pokemon.hasAbility?(:LEVITATE)
      damage = 0
    end
    if safe_side_effect(side, :StealthRock, false)
      rock = PBTypes.const_get("ROCK") rescue nil
      if rock
        effectiveness = PBTypes.getCombinedEffectiveness(
          rock, pokemon.type1, pokemon.type2, -1
        )
        damage += 12.5 * effectiveness.to_f / 8.0
      else
        damage += 12.5
      end
    end
    damage
  rescue
    0
  end

  # Which attacking stat this battler actually hits with. The burn, paralysis and
  # stat-drop rows all ask it, and stock v16 asks the same question with pbRoughStat
  # (085:2930).
  def self.attack_bias(battle, battler, skill)
    return [false, false] if !battler
    attack = (battle.pbRoughStat(battler, PBStats::ATTACK, skill) rescue nil)
    special = (battle.pbRoughStat(battler, PBStats::SPATK, skill) rescue nil)
    return [false, false] if attack.nil? || special.nil?
    [attack > special, special > attack]
  rescue
    [false, false]
  end

  # kind / stat / chance for one move against one target, all three from the engine.
  # The chance is the move's own addlEffect, doubled by Serene Grace or a Rainbow and
  # zeroed when the secondary is negated -- the same two conditions the engine itself
  # checks before rolling for it (080:3058-3065).
  def self.move_effect(battle, move, battler, target)
    code = (move.function rescue nil)
    return [nil, nil, nil] if code.nil?
    entry = MOVE_EFFECT_CODES[code]
    return [nil, nil, nil] if !entry
    chance = (move.addlEffect rescue 0).to_i
    # A status MOVE (Will-O-Wisp, Toxic, Thunder Wave) carries addlEffect 0 because the
    # status is its whole point, not a secondary; those are certain.
    chance = 100 if !move.pbIsDamaging? || chance <= 0
    if target && move.pbIsDamaging?
      return [entry[0], entry[1], 0] if secondary_negated?(move, battler, target)
      chance *= 2 if serene_grace?(battler) && (move.function rescue 0) != 0xA4
    end
    # A secondary that cannot land is worth nothing, and only the engine knows why not.
    if target
      verdict = engine_can_status?([entry[0]], battler, target)
      return [entry[0], entry[1], 0] if verdict == false
    end
    chance = 100 if chance > 100
    [entry[0], entry[1], chance]
  rescue
    [nil, nil, nil]
  end

  # 080:3059-3061: Sheer Force cancels the secondary outright, and Shield Dust does
  # unless the user has Mold Breaker.
  def self.secondary_negated?(move, battler, target)
    return true if (battler.hasWorkingAbility(:SHEERFORCE) rescue false)
    return false if (battler.hasMoldBreaker rescue false)
    (target.hasWorkingAbility(:SHIELDDUST) rescue false) ? true : false
  rescue
    false
  end

  def self.serene_grace?(battler)
    return true if (battler.hasWorkingAbility(:SERENEGRACE) rescue false)
    (safe_side_effect(battler.pbOwnSide, :Rainbow, 0).to_i > 0 rescue false)
  rescue
    false
  end

  def self.multi_hit?(move)
    return true if (move.pbIsMultiHit rescue false)
    MULTI_HIT_CODES.include?((move.function rescue nil))
  rescue
    false
  end

  def self.positive_stages(battler)
    return 0 if !battler
    total = 0
    battler.stages.each { |stage| total += stage if stage && stage > 0 }
    total
  rescue
    0
  end

  # Universal facts about a NON-DAMAGING move that make it unusable, so the core can
  # stop paying fresh_status +25 for a move the engine will refuse. Mirrors the Reborn
  # adapter's status_blocked? (:1154-1204) against Realidea's own engine, which
  # diverges in three places, each verified in 080_PokeBattle_Battler.rb:
  #
  # 1. Magic Bounce here bounces only moves carrying the Magic Coat flag (flag c,
  #    082_PokeBattle_Move.rb:236) and is turned off by Mold Breaker (:2433). Reborn
  #    reflects every status move and reads the partner's ability too; neither is true
  #    in this engine, so neither is modelled.
  # 2. Prankster is a PRIORITY MODIFIER ONLY here (084:1108, 080:2618). There is no
  #    Dark-type immunity to it anywhere in the build, so the Reborn clause that skips
  #    a Prankster status move into a Dark type is deliberately absent -- modelling it
  #    would make the AI refuse a move that lands.
  # 3. The pbCan*? predicates take the ATTACKER first (081:5-553), not just a
  #    showMessages flag.
  def self.status_blocked?(move, tags, battler, target)
    return false if !target
    return false if !tags.include?("status")
    return true if magic_bounced?(move, battler, target)
    # Thunder Wave into Ground, Toxic into Steel: a typed status move is refused by the
    # engine's own type verdict, which the damaging-move `immune` path never saw
    # because a status move has no base damage.
    if tags.include?("typed_status")
      return true if type_effectiveness_raw(move, battler, target) <= 0
    end
    # Leech Seed sets PBEffects::LeechSeed, not a status CONDITION, so no pbCan*?
    # predicate sees it and a seeded foe looked fresh every turn. The three failure
    # conditions are PokeBattle_Move_0DC#pbEffect (083:6296-6310) exactly.
    if tags.include?("drain")
      return true if safe_effect(target, :LeechSeed, -1).to_i >= 0
      return true if safe_effect(target, :Substitute, 0).to_i > 0
      return true if battler_has_type?(target, :GRASS)
    end
    # Yawn is the same shape one move over: tagged ["status", "sleep"], so the engine
    # check below is pbCanSleep?, which answers about the status CONDITION and says yes
    # about a target that is merely drowsy. The engine's second guard is a separate
    # line, PokeBattle_Move_004#pbEffect (083:189).
    if tags.include?("drowsy") && rule_enabled?("yawn_gate")
      return true if safe_effect(target, :Yawn, 0).to_i > 0
    end
    verdict = engine_can_status?(tags, battler, target)
    return !verdict if !verdict.nil?
    # Rescue path for an engine that does not expose the predicates.
    return true if tags.include?("burn") && battler_has_type?(target, :FIRE)
    return true if tags.include?("poison") &&
                   (battler_has_type?(target, :POISON) || battler_has_type?(target, :STEEL))
    return true if tags.include?("powder") && battler_has_type?(target, :GRASS)
    return true if tags.include?("paralyze") && battler_has_type?(target, :ELECTRIC)
    false
  rescue
    false
  end

  # true/false from the engine, or nil when this move applies no status the engine can
  # be asked about (so the caller falls through to the type list). showMessages is
  # false: these predicates print "But it failed!" otherwise.
  def self.engine_can_status?(tags, battler, target)
    return target.pbCanBurn?(battler, false)     if tags.include?("burn")
    return target.pbCanPoison?(battler, false)   if tags.include?("poison")
    return target.pbCanParalyze?(battler, false) if tags.include?("paralyze")
    return target.pbCanSleep?(battler, false)    if tags.include?("sleep")
    return target.pbCanFreeze?(battler, false)   if tags.include?("freeze")
    return target.pbCanConfuse?(battler, false)  if tags.include?("confuse")
    nil
  rescue
    nil
  end

  def self.magic_bounced?(move, battler, target)
    return false if !(move.canMagicCoat? rescue false)
    return false if (battler.hasMoldBreaker rescue false)
    ability_key(target) == "MAGICBOUNCE"
  rescue
    false
  end

  # The engine's raw type verdict on the 8-is-neutral scale, for a move with no base
  # damage (type_effectiveness returns a flat 1.0 for those).
  def self.type_effectiveness_raw(move, attacker, target)
    move.pbTypeModifier(move.type, attacker, target).to_i
  rescue
    8
  end

  def self.battler_has_type?(battler, symbol)
    battler.pbHasType?(symbol)
  rescue
    type = (PBTypes.const_get(symbol) rescue nil)
    return false if type.nil?
    battler.type1 == type || battler.type2 == type
  end

  def self.safe_effect(battler, name, fallback)
    return fallback if !PBEffects.const_defined?(name.to_s)
    value = PBEffects.const_get(name.to_s)
    battler.effects[value]
  rescue
    fallback
  end

  def self.safe_side_effect(side, name, fallback)
    return fallback if !PBEffects.const_defined?(name.to_s)
    value = PBEffects.const_get(name.to_s)
    side.effects[value]
  rescue
    fallback
  end

  def self.safe_field_effect(battle, name, fallback)
    return fallback if !PBEffects.const_defined?(name.to_s)
    value = PBEffects.const_get(name.to_s)
    battle.field.effects[value]
  rescue
    fallback
  end

  # Ability and item names as uppercase strings, resolved through the CONSTANT tables
  # rather than through PBAbilities.getName / PBItems.getName -- getName goes to the
  # compiled message file, which in this build is Spanish, and returns an empty string
  # for every id in the probe/gauntlet environment that has no message data loaded.
  # The constants come from Data/Constants.rxdata and are always there.
  def self.ability_key(battler_or_pokemon)
    value = (battler_or_pokemon.ability rescue nil)
    return nil if value.nil? || value == 0
    constant_key(PBAbilities, :@ability_keys, value)
  rescue
    nil
  end

  # Uppercase type name ("FIRE"), the same shape the core's absorb and redirect tables
  # are keyed by. Built once from PBTypes, like move_key.
  def self.type_key(id)
    return nil if id.nil?
    constant_key(PBTypes, :@type_keys, id)
  end

  def self.item_key(battler_or_pokemon)
    value = (battler_or_pokemon.item rescue nil)
    return nil if value.nil? || value == 0
    constant_key(PBItems, :@item_keys, value)
  rescue
    nil
  end

  # A party entry exposes its held item through the same reader; kept as its own name
  # so the hazard rows read as being about a benched Pokemon.
  def self.pokemon_item_key(pokemon)
    item_key(pokemon)
  end

  def self.constant_key(namespace, cache_name, value)
    cache = instance_variable_get(cache_name)
    if !cache
      cache = {}
      namespace.constants.each do |name|
        id = namespace.const_get(name) rescue nil
        cache[id] = name.to_s.upcase if id.is_a?(Integer)
      end
      instance_variable_set(cache_name, cache)
    end
    cache[value]
  rescue
    nil
  end

  def self.move_key(id)
    if !defined?(@move_keys) || !@move_keys
      @move_keys = {}
      PBMoves.constants.each do |name|
        value = PBMoves.const_get(name) rescue nil
        @move_keys[value] = name.to_s.upcase if value.is_a?(Integer)
      end
    end
    @move_keys[id] || id.to_s
  end

  def self.weather_name(battle)
    weather = battle.pbWeather rescue battle.weather
    return "rain" if defined?(PBWeather::RAINDANCE) && weather == PBWeather::RAINDANCE
    return "rain" if defined?(PBWeather::HEAVYRAIN) && weather == PBWeather::HEAVYRAIN
    return "sun" if defined?(PBWeather::SUNNYDAY) && weather == PBWeather::SUNNYDAY
    return "sun" if defined?(PBWeather::HARSHSUN) && weather == PBWeather::HARSHSUN
    return "sand" if defined?(PBWeather::SANDSTORM) && weather == PBWeather::SANDSTORM
    return "hail" if defined?(PBWeather::HAIL) && weather == PBWeather::HAIL
    "none"
  end

  def self.percent(value, total)
    return 0.0 if !total || total.to_f <= 0
    value.to_f * 100.0 / total.to_f
  end

  def self.average(values)
    return 0.0 if values.empty?
    values.inject(0.0) do |sum, value|
      sum + PortableAI::Model.number(value, 0)
    end / values.length
  end

  def self.apply_action(battle, index, action)
    if action["type"] == "switch"
      return battle.pbRegisterSwitch(index, action["slot"])
    end
    return false if !battle.pbRegisterMove(index, action["slot"], false)
    target = action["target"]
    battle.pbRegisterTarget(index, target) if !target.nil? && battle.doublebattle
    true
  end

  def self.apply_memory(battle, index, action)
    memory = battle.instance_variable_get(:@portable_ai_memory) || {}
    state = memory[index.to_s] || {}
    selected_key = nil
    if action["type"] == "switch"
      selected_key = "switch"
    else
      tags = PortableAI::Effects.describe(action["move_id"], action["tags"])
      if tags.include?("setup")
        selected_key = "setup"
      elsif tags.include?("protect") || tags.include?("team_protect")
        selected_key = "protect"
      elsif tags.include?("substitute")
        selected_key = "substitute"
      end
    end
    previous_count = selected_key ? state[selected_key].to_i : 0
    %w[setup protect substitute switch].each { |key| state[key] = 0 }
    if action["type"] == "switch"
      state["switch"] = previous_count + 1
    else
      state[selected_key] = previous_count + 1 if selected_key
      state["last_move"] = action["move_id"]
    end
    state["last_type"] = action["type"]
    memory[index.to_s] = state
    battle.instance_variable_set(:@portable_ai_memory, memory)
  end

  # Run-level knobs read from Data/ai_harness.txt, in the same key=value format the
  # Reborn harness uses (AI_Harness.rb:51-64). It lives HERE rather than in the
  # gauntlet because the probe needs it too and the probe is a separate script section
  # that loads earlier -- and because the thing that consumes $PORTABLE_AI_CONFIG is
  # this module, not the benchmark that happens to set it.
  module Harness
    FILE = "Data/ai_harness.txt"

    # Core config keys a run may override, with the type each parses to. Booleans
    # become real true/false: the core tests them with plain Ruby truthiness, and the
    # string "false" is truthy. Same nineteen keys as the Reborn gauntlet
    # (Portable_AI_Gauntlet.rb:37-70), so an ablation reads identically in both studies.
    CONFIG_OVERRIDE_KEYS = [
      ["switch_risk_weight", :float],
      ["accuracy_weight",    :float],
      ["heal_gate",          :boolean],
      ["priority_gate",      :boolean],
      ["self_cost",          :boolean],
      ["strict_threat",      :boolean],
      # 0.5.0 tables. All four false is 0.4.1, which is the control run.
      ["side_effects",       :boolean],
      ["ability_rules",      :boolean],
      ["entry_rules",        :boolean],
      ["format_rules",       :boolean],
      # 0.6.0. damage_race=false is the control for the damage-race batch.
      ["damage_race",        :boolean],
      ["damage_race_switch", :boolean],
      # 0.6.2 bugfix batch, one key each so the arms can be ablated singly.
      ["spread_target_hp",   :boolean],
      ["lethal_flat",        :boolean],
      ["entry_death",        :boolean],
      ["wish_pending",       :boolean],
      ["setup_stage",        :boolean],
      ["move_memory",        :boolean],
      ["yawn_gate",          :boolean]
    ]

    def self.config
      cfg = {}
      return cfg if !File.exist?(FILE)
      File.open(FILE, "rb") do |file|
        file.read.split(/[\r\n]+/).each do |line|
          line = line.strip
          next if line.empty? || line[0, 1] == "#"
          key, value = line.split("=", 2)
          cfg[key.to_s.strip] = value.to_s.strip if key && value
        end
      end
      cfg
    rescue
      {}
    end

    def self.bool(cfg, key, fallback)
      return fallback if !cfg[key] || cfg[key] == ""
      ["true", "1", "yes", "on"].include?(cfg[key].to_s.downcase)
    end

    def self.list(cfg, key, fallback)
      return fallback if !cfg[key] || cfg[key] == ""
      out = []
      cfg[key].to_s.split(",").each do |part|
        part = part.strip
        out << part.to_i if part != ""
      end
      out.empty? ? fallback : out
    end

    def self.config_overrides_from(cfg)
      overrides = {}
      CONFIG_OVERRIDE_KEYS.each do |key, kind|
        value = cfg[key]
        next if !value || value == ""
        overrides[key] = (kind == :float) ? value.to_f : (value == "true")
      end
      overrides
    end

    # Install this run's overrides for the duration of the block and hand the block the
    # raw config so it can read its own non-core keys (trace, seeds, append).
    def self.with_config
      cfg = config
      $PORTABLE_AI_CONFIG = config_overrides_from(cfg)
      yield cfg
    ensure
      $PORTABLE_AI_CONFIG = nil
    end
  end

  def self.log_error(error, index)
    signature = "#{error.class}: #{error.message}"
    return if defined?(@last_error) && @last_error == signature
    @last_error = signature
    File.open(ERROR_FILE, "ab") do |file|
      file.write("actor=#{index} #{signature}\n")
      file.write(error.backtrace[0, 8].join("\n") + "\n") if error.backtrace
    end
  rescue
  end
end

class PokeBattle_Battle
  if !method_defined?(:portable_ai_stock_pbChooseMoves)
    alias portable_ai_stock_pbChooseMoves pbChooseMoves
  end
  if !method_defined?(:portable_ai_stock_pbDefaultChooseEnemyCommand)
    alias portable_ai_stock_pbDefaultChooseEnemyCommand pbDefaultChooseEnemyCommand
  end

  def portable_ai_last_plan
    @portable_ai_last_plan
  end

  def pbChooseMoves(index)
    if PortableAIRealidea.enabled_for?(self, index)
      return if PortableAIRealidea.choose(self, index)
    end
    portable_ai_stock_pbChooseMoves(index)
  end

  def pbDefaultChooseEnemyCommand(index)
    if PortableAIRealidea.enabled_for?(self, index) && pbCanShowCommands?(index)
      return if pbEnemyShouldUseItem?(index)
      if pbCanShowFightMenu?(index)
        return if pbAutoFightMenu(index)
        pbRegisterMegaEvolution(index) if pbEnemyShouldMegaEvolve?(index)
      end
      return if PortableAIRealidea.choose(self, index)
    end
    portable_ai_stock_pbDefaultChooseEnemyCommand(index)
  end
end
# ===== END adapters/realidea/Portable_AI_Adapter.rb =====

# ===== BEGIN adapters/realidea/Portable_AI_Gauntlet.rb =====
# Opt-in frozen strength benchmark for Realidea.
#
# Create Data/ai_gauntlet.txt and launch the game. The existing AIProbe boot branch
# delegates here, runs stock and Portable AI against the same teams/seeds, and writes
# Data/ai_gauntlet_results.ndjson without opening a save file.
#
# Data/ai_harness.txt (optional) sets run-level knobs, one key=value per line:
#   any of PortableAIRealidea::Harness::CONFIG_OVERRIDE_KEYS -- override that core
#     config key for the whole run, so a policy A/B is two runs of one build rather
#     than two builds. Whatever is set is stamped on every record.
#   trace=true   -- record the per-turn portable decision trace (default false; it was
#                   unconditional through 0.1.0 and dominated the file size)
#   seeds=a,b,c  -- replace the five default seeds
#   matchups=x,y -- run only these named matchups from the schedule
#   append=true  -- append to the results file instead of truncating it
#   teams=NAME   -- roster set (default "archetype", the frozen three-mon fixture).
#                   The tier sets gen6ou_a/gen6ou_b are real gen 6 OU sample teams;
#                   see tools/make_tier_teams.py --game realidea.
#   schedule=tier -- every ordered non-mirror pairing of the set's four teams in
#                   singles (12 matchups), written to its own results file so tier
#                   numbers can never pool with the frozen eight-matchup benchmark.
#   mega=false   -- suppress Mega Evolution (default on; see run_with)

class PortableAIGauntletScene < AIProbeNullScene
  def pbStartBattle(battle)
    @battle = battle
  end

  def pbChooseNewEnemy(index, party)
    @battle.pbDefaultChooseNewEnemy(index, party)
  end

  def pbDisplayConfirmMessage(msg)
    false
  end

  def pbShowCommands(msg, commands, default_value)
    default_value || 0
  end
end

module PortableAIGauntlet
  TRIGGER = "Data/ai_gauntlet.txt"
  OUT     = "Data/ai_gauntlet_results.ndjson"
  SUMMARY = "Data/ai_gauntlet_summary.txt"
  TIER_OUT     = "Data/ai_tier_results.ndjson"
  TIER_SUMMARY = "Data/ai_tier_summary.txt"
  PROGRESS     = "Data/ai_gauntlet_progress.txt"
  ERRLOG       = "Data/ai_gauntlet_error.txt"
  SEEDS   = [104729, 130363, 155921, 196613, 262147]

  DEFAULT_TEAM_SET = "archetype"

  TEAMS = {
    "offense" => [
      ["GARCHOMP",  %w[EARTHQUAKE DRAGONCLAW SWORDSDANCE PROTECT]],
      ["MAGNEZONE", %w[THUNDERBOLT FLASHCANNON THUNDERWAVE PROTECT]],
      ["GENGAR",    %w[SHADOWBALL SLUDGEBOMB WILLOWISP DESTINYBOND]]
    ],
    "balance" => [
      ["SKARMORY", %w[BRAVEBIRD ROOST STEALTHROCK WHIRLWIND]],
      ["SNORLAX",  %w[BODYSLAM CRUNCH REST SLEEPTALK]],
      ["STARMIE",  %w[SURF PSYCHIC RECOVER THUNDERBOLT]]
    ],
    "bulky" => [
      ["UMBREON",   %w[FOULPLAY TOXIC MOONLIGHT PROTECT]],
      ["FERROTHORN", %w[POWERWHIP GYROBALL LEECHSEED STEALTHROCK]],
      ["TOXAPEX",   %w[SCALD RECOVER TOXIC HAZE]]
    ],
    "speed" => [
      ["ALAKAZAM", %w[PSYCHIC SHADOWBALL DAZZLINGGLEAM RECOVER]],
      ["CROBAT",   %w[BRAVEBIRD CROSSPOISON UTURN ROOST]],
      ["WEAVILE",  %w[ICICLECRASH KNOCKOFF ICEshard SWORDSDANCE]]
    ]
  }

  # The frozen benchmark: eight matchups over the three-mon archetype fixture. Every
  # 0.1.0 number was measured on exactly these, so they do not change.
  MATCHUPS = [
    ["offense_vs_balance", "offense", "balance", false],
    ["balance_vs_offense", "balance", "offense", false],
    ["bulky_vs_speed", "bulky", "speed", false],
    ["speed_vs_bulky", "speed", "bulky", false],
    ["offense_vs_bulky", "offense", "bulky", false],
    ["speed_vs_balance", "speed", "balance", false],
    ["double_offense_balance", "offense", "balance", true],
    ["double_speed_bulky", "speed", "bulky", true]
  ]

  # Every ordered non-mirror pairing of a roster's four teams. Team keys are generic
  # (team1..team4) across every tier set, so the schedule is identical set to set and
  # the two sets stay comparable.
  def self.tier_matchups(teams)
    names = teams.keys.sort
    out = []
    names.each do |left|
      names.each do |right|
        out << ["#{left}_vs_#{right}", left, right, false] if left != right
      end
    end
    out
  end

  def self.team_set(name)
    sets = PortableAIRealideaTeams::SETS
    teams = sets[name]
    if !teams
      raise "unknown team set #{name.inspect}; available: #{sets.keys.sort.join(', ')}"
    end
    teams
  end

  def self.requested?
    File.exist?(TRIGGER)
  rescue
    false
  end

  def self.command_phase(battle)
    scene = battle.scene
    scene.pbBeginCommandPhase
    scene.pbResetCommandIndices
    PortableAIRealidea.clear_cache(battle)

    for index in 0...4
      battler = battle.battlers[index]
      battler.effects[PBEffects::SkipTurn] = false if battler
      if battler && (battle.pbCanShowCommands?(index) || battler.isFainted?)
        battle.choices[index][0] = 0
        battle.choices[index][1] = 0
        battle.choices[index][2] = nil
        battle.choices[index][3] = -1
      end
    end
    mega = battle.megaEvolution
    for side in 0...mega.length
      for owner in 0...mega[side].length
        mega[side][owner] = -1 if mega[side][owner] >= 0
      end
    end

    for index in 0...4
      battler = battle.battlers[index]
      next if !battler || battler.isFainted?
      next if !battle.pbCanShowCommands?(index)
      battle.pbDefaultChooseEnemyCommand(index)
    end
  end

  # One line per battle, flushed as it goes. The results file only gains a record when
  # a battle finishes, so without this a run that stops mid-battle is indistinguishable
  # from one that never started.
  def self.note(line)
    begin
      File.open(PROGRESS, "ab") { |file| file.write(line + "\n") }
    rescue
      nil
    end
  end

  def self.run
    begin
      File.open(PROGRESS, "wb") { |file| file.write("") }
      File.delete(ERRLOG) if File.exist?(ERRLOG)
    rescue
      nil
    end
    PortableAIRealidea::Harness.with_config { |cfg| run_with(cfg) }
  rescue Exception => error
    # Anything thrown outside run_one's own rescue used to surface as nothing at all:
    # mkxp raises its modal error box, the process then sits in the window message pump
    # at ~0.015 CPU-seconds per five wall seconds, and the results file is empty with no
    # statement anywhere of what went wrong. That is the shape the 0.6.2 "gauntlet hang"
    # was reported in. It is a crash, and this is where it becomes readable.
    begin
      File.open(ERRLOG, "wb") do |file|
        file.write("#{error.class}: #{error.message}\n")
        file.write(((error.backtrace || [])[0, 15]).join("\n") + "\n")
      end
    rescue
      nil
    end
  end

  def self.run_with(cfg)
    AIProbe.bootstrap
    AIProbe.install_exception_capture
    trace = PortableAIRealidea::Harness.bool(cfg, "trace", false)
    seeds = PortableAIRealidea::Harness.list(cfg, "seeds", SEEDS)
    mode_flag = PortableAIRealidea::Harness.bool(cfg, "append", false) ? "ab" : "wb"

    set_name = (cfg["teams"] && cfg["teams"] != "") ? cfg["teams"] : DEFAULT_TEAM_SET
    begin
      teams = team_set(set_name)
    rescue RuntimeError => error
      note("Gauntlet: #{error.message}")
      return
    end
    tier = cfg["schedule"] == "tier"
    matchups = tier ? tier_matchups(teams) : MATCHUPS
    # Named subset, for smoke-testing a new roster cheaply and for resuming a run past
    # a matchup that stalled without re-fighting the ones already on disk.
    if cfg["matchups"] && cfg["matchups"] != ""
      wanted = cfg["matchups"].split(",").map { |name| name.strip }
      matchups = matchups.select { |matchup| wanted.include?(matchup[0]) }
    end
    if matchups.empty?
      note("Gauntlet: no matchups matched #{cfg['matchups'].inspect}")
      return
    end
    out     = tier ? TIER_OUT : OUT
    summary = tier ? TIER_SUMMARY : SUMMARY

    # Realidea gates Mega Evolution on two story switches that a save-less harness
    # leaves false (pbCanMegaEvolve?, PokeBattle_Battle.rb:1967), so without this a
    # Tyranitar holding Tyranitarite is just a Tyranitar holding a rock -- and the
    # gen 6 rosters are built around megas. Both arms reach it by the same path:
    # stock and Portable both call pbRegisterMegaEvolution from
    # pbEnemyShouldMegaEvolve?, so this changes the teams, never the policy. On by
    # default and provably inert for the archetype fixture, whose mons hold no stone:
    # pbCanMegaEvolve? tests hasMega? before it reaches either switch.
    mega = PortableAIRealidea::Harness.bool(cfg, "mega", true)
    $game_switches[512] = mega

    old_trainer = $Trainer
    old_enabled = (defined?($PORTABLE_AI_ENABLED) ? $PORTABLE_AI_ENABLED : nil)
    counts = {
      "stock" => { "wins" => 0, "losses" => 0, "draws" => 0, "errors" => 0, "turns" => 0 },
      "portable" => { "wins" => 0, "losses" => 0, "draws" => 0, "errors" => 0, "turns" => 0 }
    }
    note("Gauntlet: #{matchups.length * seeds.length * 2} battles, " +
         "#{tier ? 'tier' : 'frozen'} schedule, teams=#{set_name}, " +
         "mega=#{mega}, portable #{PortableAI::VERSION}")

    File.open(out, mode_flag) do |file|
      matchups.each do |matchup|
        seeds.each do |seed|
          ["stock", "portable"].each do |mode|
            note("start #{matchup[0]} #{mode} seed=#{seed}")
            record = run_one(matchup, seed, mode, trace, teams, set_name, mega)
            note("  #{record['result']} turns=#{record['turns']}" +
                 (record["error"] ? " #{record['error']}" : ""))
            bucket = counts[mode]
            bucket["turns"] += record["turns"].to_i
            case record["result"]
            when "win"  then bucket["wins"] += 1
            when "loss" then bucket["losses"] += 1
            when "draw" then bucket["draws"] += 1
            else bucket["errors"] += 1
            end
            file.write(AIProbe.json(record) + "\n")
            file.flush
          end
        end
      end
    end

    File.open(summary, "wb") do |file|
      counts.each do |mode, values|
        total = values["wins"] + values["losses"] + values["draws"]
        win_rate = total > 0 ? values["wins"] * 100.0 / total : 0
        mean_turns = total > 0 ? values["turns"] * 1.0 / total : 0
        file.write("#{mode}: wins=#{values['wins']} losses=#{values['losses']} " +
                   "draws=#{values['draws']} errors=#{values['errors']} " +
                   "win_rate=#{round1(win_rate)} " +
                   "mean_turns=#{round1(mean_turns)}\n")
      end
    end
  ensure
    $Trainer = old_trainer if defined?(old_trainer)
    $PORTABLE_AI_ENABLED = old_enabled if defined?(old_enabled)
  end

  def self.run_one(matchup, seed, mode, trace = false, teams = nil,
                   set_name = DEFAULT_TEAM_SET, mega = true)
    teams ||= team_set(DEFAULT_TEAM_SET)
    id, left_name, right_name, doubles = matchup
    left_trainer = make_trainer("Stock #{left_name}")
    right_trainer = make_trainer("#{mode} #{right_name}")
    left_party = make_party(teams[left_name], left_trainer)
    right_party = make_party(teams[right_name], right_trainer)
    scene = PortableAIGauntletScene.new
    battle = PokeBattle_Battle.new(
      scene, left_party, right_party, left_trainer, right_trainer
    )
    battle.internalbattle = false
    battle.doublebattle = doubles
    battle.debug = true
    battle.items = []
    battle.instance_variable_set(:@portable_ai_gauntlet, true)
    battle.instance_variable_set(:@portable_ai_decision_trace, trace ? [] : nil)

    $Trainer = left_trainer
    $PORTABLE_AI_ENABLED = (mode == "portable")
    srand(seed)
    decision = battle.pbStartBattle(true)
    result = decision == 2 ? "win" : decision == 1 ? "loss" : "draw"
    # Same seat convention as `result`: party1 is the left, stock-piloted side, so a
    # verdict of 1 (left ahead) is a loss for the AI under test. Recorded alongside the
    # raw decision rather than folded into `result`, so no previously recorded number
    # changes meaning and a reader can choose which question to ask.
    timeout = battle.portable_ai_timeout_decision rescue nil
    record = {
      "id" => id,
      "mode" => mode,
      "seed" => seed,
      "format" => doubles ? "double" : "single",
      "left_stock_team" => left_name,
      "right_test_team" => right_name,
      "teams" => set_name,
      # Stamped because it changes the rosters, not the policy: a mega-less gen 6 team
      # is not the team its author built, and a reader must not have to guess which
      # they are looking at.
      "mega" => mega,
      "decision" => decision,
      "result" => result,
      "turns" => battle.turncount
    }
    if decision == 0 && timeout
      record["timed_out"] = true
      record["timeout_result"] =
        timeout == 2 ? "win" : timeout == 1 ? "loss" : "draw"
    end
    # Stamped on EVERY arm, not just the portable one: a stock record is only meaningful
    # as the paired baseline of the run it came from, and a readout rendered from a
    # stale baseline is the failure this stamp exists to make visible.
    record["portable_version"] = PortableAI::VERSION if defined?(PortableAI::VERSION)
    if mode == "portable"
      overrides = PortableAIRealidea.config_overrides
      record["config_overrides"] = overrides if !overrides.empty?
      captured = battle.instance_variable_get(:@portable_ai_decision_trace)
      record["trace"] = captured if captured
    end
    record
  rescue Exception => error
    {
      "id" => id,
      "mode" => mode,
      "seed" => seed,
      "format" => doubles ? "double" : "single",
      "teams" => set_name,
      "mega" => mega,
      "result" => "error",
      "turns" => 0,
      "error" => "#{error.class}: #{error.message}",
      "where" => (error.backtrace ? error.backtrace[0, 6].join(" | ") : nil),
      "portable_version" => (defined?(PortableAI::VERSION) ? PortableAI::VERSION : nil)
    }
  end

  def self.make_trainer(name)
    trainer = PokeBattle_Trainer.new(name, 0)
    def trainer.skill; 100; end
    def trainer.skillCode; ""; end
    trainer
  end

  # A spec is [SPECIES, [moves]] for the archetype fixture, or that plus a hash of
  # form/item/ability/nature/evs/ivs for a tier set. Omitting the hash reproduces the
  # fixture exactly: flat 31 IVs, 85 EVs, slot-0 ability, Hardy, no item.
  def self.make_party(specs, trainer)
    specs.map do |spec|
      species_name, move_names, extra = spec
      extra ||= {}
      species = PBSpecies.const_get(species_name)
      pokemon = PokeBattle_Pokemon.new(species, 100, trainer)
      # Forme first: a forme carries its own BaseStats and its own ability slots, so
      # setting it after the spread would build the mon from the base species' numbers.
      # form= runs the species' onSetForm hook, which for Rotom swaps an appliance move
      # into the moveset -- harmless here only because the four slots are assigned
      # immediately below. formNoCall= is the fallback because form= also calls
      # pbSeenForm, which wants a Pokedex this harness has no save file for.
      if extra["form"] && extra["form"] > 0
        begin
          pokemon.form = extra["form"]
        rescue
          pokemon.formNoCall = extra["form"]
        end
      end
      for slot in 0...4
        move_name = move_names[slot]
        next if !move_name
        # Preserve compatibility with the one mixed-case fixture spelling above.
        move_name = move_name.to_s.upcase
        pokemon.moves[slot] = PBMove.new(PBMoves.const_get(move_name))
      end
      if extra["item"]
        item = (PBItems.const_get(extra["item"]) rescue nil)
        pokemon.setItem(item) if item
      end
      pokemon.setAbility(extra["ability"] || 0)
      pokemon.setNature(extra["nature"] || 0)
      # Hidden Power carries no field in v16: its type is derived from IV parities
      # (pbHiddenPower, PokeBattle_MoveEffects.rb:3760) over a pool one type wider than
      # the generation these sets were built for. The IVs below are already solved for
      # the type the author wanted -- see Realidea.finalise_hidden_power in
      # tools/showdown_names.py -- so nothing is set here and nothing may be.
      evs = extra["evs"]
      ivs = extra["ivs"]
      for stat in 0...6
        pokemon.iv[stat] = ivs ? ivs[stat] : 31
        pokemon.ev[stat] = evs ? evs[stat] : 85
      end
      pokemon.calcStats
      pokemon.hp = pokemon.totalhp
      pokemon
    end
  end

  def self.round1(value)
    ((value * 10).round) / 10.0
  end
end

# Roster lookup, shared with the tier suite. The tier file the bundle concatenates
# after this one merges itself in here (tools/make_tier_teams.py --game realidea).
# "archetype" is the original three-mon fixture and the default, so omitting teams=
# reproduces every run recorded before roster selection existed.
module PortableAIRealideaTeams
  SETS = { "archetype" => PortableAIGauntlet::TEAMS }
end


class PokeBattle_Battle
  attr_reader :portable_ai_timeout_decision

  if !method_defined?(:portable_ai_gauntlet_stock_pbDecisionOnTime)
    alias portable_ai_gauntlet_stock_pbDecisionOnTime pbDecisionOnTime
  end

  # The 100-round cap computes a verdict on remaining count then HP total, and
  # pbStartBattle throws it away: the cap raises through pbAbort, and the rescue that
  # catches it overwrites @decision with 0 (PokeBattle_Battle.rb:2753-2755). So a
  # battle that was clearly ahead on both tiebreaks is returned as "undecided" and
  # lands in the results as a draw. Stashing the verdict on the way past costs nothing
  # and changes no behaviour -- the same value is still returned -- but it lets a
  # timeout be reported as what it was instead of being pooled with genuine ties.
  def pbDecisionOnTime
    @portable_ai_timeout_decision = portable_ai_gauntlet_stock_pbDecisionOnTime
  end

  if !method_defined?(:portable_ai_gauntlet_stock_pbCommandPhase)
    alias portable_ai_gauntlet_stock_pbCommandPhase pbCommandPhase
  end
  if !method_defined?(:portable_ai_gauntlet_stock_pbEndOfBattle)
    alias portable_ai_gauntlet_stock_pbEndOfBattle pbEndOfBattle
  end

  def pbCommandPhase
    if @portable_ai_gauntlet
      PortableAIGauntlet.command_phase(self)
    else
      portable_ai_gauntlet_stock_pbCommandPhase
    end
  end

  def pbEndOfBattle(canlose = false)
    if @portable_ai_gauntlet
      @scene.pbEndBattle(@decision)
      return @decision
    end
    portable_ai_gauntlet_stock_pbEndOfBattle(canlose)
  end
end
# ===== END adapters/realidea/Portable_AI_Gauntlet.rb =====

